/* 2015年6月8日 厚生委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h27-20150608-7","dateIso":"2015-06-08","title":"2015年6月8日 厚生委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3416#one","fetchedAt":"2026-08-14","characters":52826,"voices":[{"i":1,"speaker":"沢田委員長","text":"○午後 １時００分開会\nただいまから、厚生委員会を開会いたします。\n本日は、お手元に配付してございます審査・調査予定表のとおり、幹部職員の紹介、事務事業概要の説明を予定しております。\nまた、その他におきまして、所管事務調査および行政視察について、ご案内したいと考えておりますので、よろしくお願いいたします。\n本日も、効率的な委員会運営にご協力をよろしくお願いいたします。\n────────────────────────────────────────────\n１ 幹部職員紹介"},{"i":2,"speaker":"沢田委員長","text":"まず予定表の１、幹部職員紹介を議題に供します。\n実質的には今回が初めての委員会でございますので、改めて委員、理事者の自己紹介をお願いいたします。\nでははじめに委員長の私から行います。委員長の沢田洋和です、よろしくお願いいたします。"},{"i":3,"speaker":"鈴木（ひ）副委員長","text":"副委員長の日本共産党、鈴木ひろ子です、よろしくお願いいたします。"},{"i":4,"speaker":"石田（秀）委員","text":"自民党・子ども未来の石田です、よろしくお願いします。"},{"i":5,"speaker":"横山委員","text":"同じく横山由香理です、よろしくお願いいたします。"},{"i":6,"speaker":"いながわ委員","text":"民主党・無所属クラブのいながわです、よろしくお願いします。"},{"i":7,"speaker":"若林委員","text":"公明党の若林です、よろしくお願いします。"},{"i":8,"speaker":"新妻委員","text":"公明党の新妻さえ子でございます、よろしくお願いいたします。"},{"i":9,"speaker":"のだて委員","text":"共産党のだて稔史です、よろしくお願いいたします。"},{"i":10,"speaker":"中川原副区長","text":"副区長の中川原でございます。よろしくお願いいたします。\n以降、各部長のほうから紹介させていただきます。"},{"i":11,"speaker":"榎本（圭）福祉部長","text":"福祉部長の榎本でございます。よろしくお願いします。\nそれでは、福祉部の各課長を紹介させていただきます。\n大串福祉計画課長でございます。"},{"i":12,"speaker":"大串福祉計画課長","text":"大串です、どうぞよろしくお願いいたします。"},{"i":13,"speaker":"榎本（圭）福祉部長","text":"それから、永尾高齢者福祉課長でございます。"},{"i":14,"speaker":"永尾高齢者福祉課長","text":"永尾でございます。どうぞよろしくお願いいたします。"},{"i":15,"speaker":"榎本（圭）福祉部長","text":"それから、松山高齢者地域支援課長でございます。"},{"i":16,"speaker":"松山高齢者地域支援課長","text":"松山でございます。どうぞよろしくお願いいたします。"},{"i":17,"speaker":"榎本（圭）福祉部長","text":"中山障害者福祉課長でございます。"},{"i":18,"speaker":"中山障害者福祉課長","text":"中山です。どうぞよろしくお願いいたします。"},{"i":19,"speaker":"榎本（圭）福祉部長","text":"それから、伊東生活福祉課長でございます。"},{"i":20,"speaker":"伊東生活福祉課長","text":"伊東でございます。よろしくお願いします。"},{"i":21,"speaker":"榎本（圭）福祉部長","text":"福祉部の理事者は以上でございます。"},{"i":22,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"健康推進部長、品川保健所長兼務の矢野でございます。よろしくお願いいたします。\nそれでは、私のほうから、部内の課長の紹介をさせていただきます。まず、健康推進部から紹介させていただきます。\n川島健康課長でございます。"},{"i":23,"speaker":"川島健康課長","text":"川島でございます。よろしくお願いいたします。"},{"i":24,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"次に、高森国保医療年金課長でございます。"},{"i":25,"speaker":"高森国保医療年金課長","text":"高森です。よろしくお願いします。"},{"i":26,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"次に、品川区保健所の課長のほうを紹介させていただきます。\n高山生活衛生課長でございます。"},{"i":27,"speaker":"高山生活衛生課長","text":"高山でございます。どうぞよろしくお願いいたします。"},{"i":28,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"舟木保健予防課長でございます。"},{"i":29,"speaker":"舟木保健予防課長","text":"舟木です。よろしくお願いいたします。"},{"i":30,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"太田品川保健センター所長でございます。"},{"i":31,"speaker":"太田品川保健センター所長","text":"太田でございます。よろしくお願いします。"},{"i":32,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"島袋大井保健センター所長でございます。"},{"i":33,"speaker":"島袋大井保健センター所長","text":"島袋でございます。よろしくお願いいたします。"},{"i":34,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"榎本（芳）荏原保健センター所長でございます。"},{"i":35,"speaker":"榎本（芳）荏原保健センター所長","text":"榎本でございます。どうぞよろしくお願いします。"},{"i":36,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"以上でございます。よろしくお願い申し上げます。"},{"i":37,"speaker":"沢田委員長","text":"書記をお願いします。"},{"i":38,"speaker":"今井書記","text":"厚生委員会を担当させていただきます、今井と申します。よろしくお願いいたします。"},{"i":39,"speaker":"齋藤書記","text":"齋藤と申します。よろしくお願いいたします。"},{"i":40,"speaker":"沢田委員長","text":"それぞれありがとうございました。なお、事務局からは、今井書記と齋藤書記が当委員会の事務にあたりますので、よろしくお願いいたします。\nこのメンバーで１年間、実りある委員会にしてまいりたいと思いますので、改めてよろしくお願いいたします。\n以上で本件を終了いたします。\n────────────────────────────────────────────\n２ 事務事業概要"},{"i":41,"speaker":"沢田委員長","text":"それでは、予定表２の事務事業概要を議題に供します。\nこの事務事業概要につきましては、例年にならい、新しい委員で構成される最初の委員会で、各所管の事務について概要説明を受けるものでございます。\nしたがいまして、具体的な質疑につきましては、今後、取り上げていく報告事項等の案件の中で行っていただきたいと思いますので、本日は説明、質疑とも簡潔にお願いいたします。よろしくお願いいたします。\nなお、進め方でございますが、予定表に記載してあるとおり、まず(1)の福祉部から一括して説明をしていただき、質疑に移りたいと思います。その後、(2)の健康推進部・品川区保健所の所管分について説明をしていただき、同様に質疑に入ります。\nそれでは、福祉部の事務事業概要について、一括してご説明をお願いいたします。"},{"i":42,"speaker":"榎本（圭）福祉部長","text":"それでは、私のほうから、全体的な福祉部の課題ということで、説明をさせていただきます。\nまず１点目は、平成２７年４月に組織改正がありまして、去年度までは健康福祉事業部という形であったのですが、福祉部と健康推進部の二部体制というふうに分かれております。それぞれの行政課題にきめ細かく対応していきたいと思っております。\n課の組織、それから事務分掌は、後ほど説明をさせますので、まず組織改正があったということが１点目です。\nそれから、福祉部としての課題としては大きく三つ、高齢者福祉、障害者福祉、生活福祉でございます。まず、高齢者福祉につきましては、第六期介護保険事業計画の着実な遂行ということで、大きく介護保険事業の中では、平成３７年度を見据えた地域包括ケアシステムの構築と推進ということで、今年、介護保険制度の法律が変わりましたけれども、保険制度が持続可能なものとして進んでいくとともに、介護予防、日常生活支援総合事業等を充実していくものでございます。\n介護保険の二つ目としては、セーフティネットとしての施設の充実と整備ということで、団塊の世代の方々が後期高齢者となる平成３７年を見据え、在宅介護のセーフティネットとしての介護保険施設の整備・検討をしていくものでございます。\nそれから、障害者福祉につきましては、品川区障害者計画・障害者福祉計画ということで、今年度からスタートしておりますので、その中にうたっている基本方針に沿って進めたいと思っております。\n基本方針は三つあるのですけれども、一つ目は障害者のライフステージを通しての総合的、継続的な支援。二つ目は障害者の主体性の尊重、三つ目は、ともに生き、ともに暮らす地域社会の実現ということで、障害者計画の中にうたっているものを進めていきたいと思っております。\n三つ目の生活福祉の関係でございますけれども、生活保護制度とともに、この４月から生活困窮者自立支援制度が動き出しまして、相談窓口として、新たに「暮らし・しごと応援センター」という窓口を置いておりますので、更なる相談支援の充実を図っていきたいと思っております。\nそれから、特に記載はしていないのですが、会計区分では、一般会計のほか、特別会計として介護保険特別会計ということで、予算規模２３４億円の会計を所管しているものでございます。\nそれぞれの課の事務事業の内容につきまして、各課長から説明させますので、よろしくお願いいたします。"},{"i":43,"speaker":"大串福祉計画課長","text":"私からは、組織改正について、ということでご説明させていただければと思います。また、改めて福祉計画課の事務事業についても、ご説明をさせていただきたいと思います。\nそれでは、既に配付しております事務事業概要の１ページをお開きいただきたいと思います。先ほど、福祉部長からもありましたが、平成２７年４月に組織改正を行っております。大きくは、健康福祉事業部を福祉部門と健康部門に分割いたしまして、二部体制としております。\n福祉部は、福祉計画課を部の庶務担当課とし、高齢者福祉課、高齢者地域支援課、障害者福祉課、生活福祉課の５課、１９２名で、地域福祉、高齢者福祉、障害者福祉、生活福祉などを所管いたします。\nそれでは、課ごとに説明を行ってまいります。まず、福祉計画課でございます。こちらには庶務係を設けまして、日赤や共同募金、高齢者のお祝い事業のほか、部の庶務担当機能を担います。また、地域福祉の推進を図るため、民生委員担当主査を高齢者福祉課から移しているところでございます。それ以外の担当につきましては、昨年と変更しておりません。\n次に、高齢者福祉課でございます。こちらにつきましては、今後の高齢化の進展を見据え、機能的な組織となるよう組織改正を行っております。まず、右のほうの支援調整係、下線が引かれておりますが、ここでは、介護保険制度の運営、介護保険事業計画のほか、社会福祉協議会、その他の社会福祉法人の連絡調整などを行います。また、従前の認定給付係を介護認定係と介護給付係に分けまして、介護給付係では、給付管理と介護サービス事業所の指導監査事務を担当し、給付の適正化を図ってまいります。\nまた、高齢者の支援に関しましては、高齢者支援第一係と高齢者支援第二係、こちらの地区別２係制といたしまして、丁寧なケースワークを推進するというものでございます。\n次に、新たに施設支援係と、保険医療・認知症対策係を設けております。施設支援係は、施設等に入所中の高齢者の支援や特別養護老人ホームの入所調整、こういったものを担当いたします。保険医療・認知症対策係は、認知症高齢者などへの支援や医療機関との連携調整、こういったものを図ってまいるというところでございます。\n次に、従前の高齢者いきがい課は、高齢者福祉課の下にございます高齢者地域支援課となりました。今般の介護保険制度改正に合わせまして、新しい総合事業の推進を図るための体制に改正をしたところでございます。介護予防推進係では、介護保険日常生活総合事業とともに、高齢者のいきがい事業を担当させていただきます。また、今後、高齢者介護を充実していくには、医療と介護の連携は欠かせないものでございます。介護保険事業計画の重点課題である地域包括ケアシステムの構築と推進のため、健康推進部とも十分に連携を図って行ってまいりたいと思っております。\nなお、障害者福祉課では、品川区障害者計画・障害者福祉計画の着実な遂行、生活福祉課につきましては、生活困窮者自立支援の充実ということで、さまざまな課題がございますが、この組織体制で対応してまいります。\n続きまして、福祉計画課の事務事業について、ご説明していきたいと思います。２ページをお開きいただきたいと思います。先ほどもご説明いたしましたが、今年度より、組織改正により、福祉部の庶務担当課となりました。事務分掌といたしましては、地域福祉の推進、社会福祉法人の指導監査、高齢者福祉施設の整備、民生委員、こちらを所管しております。\nそれでは、具体の事務事業となりますが、少しページが飛びますが、恐れ入りますが５１ページをお開きいただきたいと思います。\nまず５１ページ、(3)、成年後見利用支援事業でございます。品川区社会福祉法人の成年後見センターと連携いたしまして、判断力が十分ではない方の財産管理や身上監護、こういったものを支援しているものでございます。\n恐れ入ります、また少し飛びますが、６６ページをお開きいただきたいと思います。ひとり暮らし等高齢者のための事業でございますが、まず１、安否確認事業でございます。こちらの(1)、緊急通報システムにつきましては、今年度より、利用者の負担を軽減するため、利用料金の減額を行っております。介護保険第１から第６段階の方については、月額５００円から３００円。介護保険第７から第１３段階の方は月額１,８００円から１,０００円に変更しております。\n内容でございますが、自宅内での緊急時に救急ペンダントのボタンを押すことにより、または、一定時間動作確認センサーに反応しない場合、あるいは、火災警報機が作動した場合に、民間受信センターから派遣員が即時援助に駆けつけるというものでございます。\n恐れ入ります、次に６９ページをお開きください。(4)、高齢者福祉電話事業でございます。こちらにつきましては、福祉電話の貸与や電話訪問等を通じまして、ひとり暮らし等高齢者の安否確認を行っております。\n恐れ入ります、７０ページをお開きいただきたいと思います。(5)、高齢者見守りネットワーク事業でございます。社会問題にもなっている孤立死を未然に防ぐため、地域社会から孤立しがちな高齢者の生活基盤を、町会や自治会を主体とする見守り活動によりまして、地域で見守っていくものでございます。現在、助成を受けている町会・自治会の数は、平成２６年度実績で４５団体となっております。活動開始から３年間は年間１０万円を上限に、また４年目、５年目は５万円の助成を行っておりましたが、今年度より、活動期間が６年目以降となります町会・自治会にも、従前は年間２万円の助成といったところでしたが、こちらを５万円に増額して助成を行うこととしております。\n次に、隣の７１ページでございます。(6)、（仮称）ふれあいステーション事業（支え愛・ほっとステーション事業）でございます。いわゆる介護保険の対象とならない日常生活の中での困り事や、生活課題を抱えているひとり暮らしの高齢者等に対しまして、コーディネーターによる相談や訪問活動、こういったものを実施しているといったところでございます。\n現在は、品川第二地区と荏原第二地区の２カ所で行っておりますが、今年度は新たに大井第二地区、大崎第二地区、こちらの２カ所を開設いたしまして、合計４カ所に拡充するものでございます。\n恐れ入ります、７３ページをお開きください。２、高齢者地域配食サービスです。こちらは、品川区商店街連合会やボランティアの皆様の協力により実施しているところでございます。\n恐れ入ります、少し飛びますが、７６ページをお開きいただきたいと思います。４、民生委員でございます。民生委員・児童委員は、福祉事務所や児童相談所などの関係機関と協力いたしまして、高齢者や障害者、子育て家庭や生活困窮家庭などの相談に応じ、助言や援助等、さまざまな活動を行っております。また、品川区では、高齢者相談員も兼務しており、１ページ先の７８ページになりますけれども、高齢者相談等事業としても活動をしていただいております。また、増大する高齢者人口と、それに伴う困難ケースの増加という状況を踏まえまして、７８ページの内容のところの下段になっておりますが、活動費、月額５,０００円だったところを７,０００円ということで増額をしております。\n恐れ入ります、次に８０ページをお開きいただきたいと思います。【４】、生きがいづくりと社会参加促進事業でございます。中ほどになりますが、(2)、長寿お祝い事業でございます。新１００歳、白寿、卒寿等のお祝いの節目に当たる方々に、品川区内の共通商品券を贈呈いたしまして、高齢者の長寿をお祝いするものでございます。昨年度の新１００歳の方は７６名ということでございました。\n次に、飛びまして、恐れ入ります、９７ページをお開きいただきたいと思います。【６】、施設等基盤整備でございます。１、施設整備でございますが、平成２７年度は、平塚橋会館跡の特別養護老人ホームの翌年度開設に向けた工事を行い、上大崎三丁目の旧みやこ荘跡の特別養護老人ホームの整備の施工に着手いたします。また、８月には、大井六丁目に、寄贈物件を活用いたしましてグループホームを開設するほか、東五反田四丁目にグループホームの整備を進めております。また、民間事業者等が区内に整備する地域密着型のサービス施設につきましても、この整備費の一部を助成してまいるところでございます。\n恐れ入ります、１枚おめくりいただきまして、次のページでございます。【７】、社会福祉法人の許認可および指導監査事務事業でございます。地域主権改革第二次一括法の施行に伴う社会福祉法の一部改正を受けまして、平成２５年４月１日より、東京都から区へ権限委譲されたものでございます。対象は、区内のみに事業所が所在する社会福祉法人１２法人で、こちらの定款変更の許可や変更届、また指導監査を行うほか、新しい法人の設立認可の事務を行うものでございます。\n次のページでございます、９９ページ、【８】、地域における福祉でございます。１、地域福祉推進事業ですが、平成２３年４月に策定いたしました第二期品川区地域福祉計画の着実な実施に向け、評価、検証を行いながら、推進を行っているところでございます。\n１枚おめくりいただきまして、１００ページになります。２、やさしいまちづくり推進費でございますが、「品川区すべての人にやさしいまちづくり推進計画」に基づきまして、ハード整備と同時に、おたがいさま運動やユニバーサルデザインの普及啓発など、ソフト面での推進を図っているところでございます。\n次に１０１ページでございますが、３、日本赤十字社品川区地区事業といたしまして、(1)、赤十字会員募集運動、(2)、災害救援品の支給、(3)、災害義援金の受付、こういったものを行っております。\nまた、４、共同募金事業でございますが、こちらにも取り組んでいるところでございます。"},{"i":44,"speaker":"永尾高齢者福祉課長","text":"それでは、私からは、高齢者福祉課の事務事業ついてご説明させていただきます。\n１ページをお開きください。高齢者福祉課は８係で構成されており、職員数は、合計５７人でございます。事務分掌につきましては、次の２ページ、３ページに記載のとおりでございます。\nそれでは、５ページをお開きください。高齢者福祉について、ご説明いたします。\n１、高齢者の人口でございます。まずこちらの表をご覧ください。平成２７年４月１日現在の６５歳以上の人口は７万８,７３９人、人口比では２１.０７％でございます。男女比で見ますと、男性が４２.５４％、女性が５７.４６％、また７５歳以上を見ますと、人口５万５,８４０人、人口比では１４.９４％、男性は３９.７％、女性は６０.３１％となっております。\n高齢者人口は、今後、上昇がさらに見込まれ、平成２９年度には、７５歳以上の人口が６５歳から７４歳を上回って、平成３７年にはさらに６５歳以上の高齢者が総人口の２２.５％を超えると推計されております。\n次に、２、施策の考え方でございます。品川区の高齢者を支えるしくみとして、右下にある表のとおり、高齢者像を三つの類型に分け、高齢者の心身状況に合わせたサービスの提供体制を整備するとともに、地域の総合支援活動や社会福祉参加の仕組みづくりにも力を入れ、構築、運用をしてきております。\nこちらの図の中にあるように、元気な高齢者、約６万４,０００人おりますけれども、高齢者社会参加プログラムを行っております。また、自立支援高齢者に対しては、自立支援ネットワークを、要介護高齢者には、在宅介護支援システムにより、在宅生活を支えております。\n次のページをお開きください。区では、適切なケアマネジメントのもと、在宅生活を可能な限り追求し、その継続が困難になった場合には、施設への入所、入居につなげております。平成２７年度から平成２９年度までの第六期介護保険事業計画期間では、介護保険制度を今後とも持続可能なものにしていくために、重点課題として、平成３７年を見据えた地域包括ケアシステムの構築と推進、セーフティネットとしての施設の充実と整備を掲げ、地域で支える仕組みである地域包括ケアシステムの構築に取り組んでまいります。\n第六期では、下の図のように、計画を推進する七つのプロジェクトに基づいて、高齢者の保健福祉の充実を図ってまいります。\n次のページになります。(2)、在宅介護支援システムの強化と地域包括支援センターの機能の充実でございます。区では、高齢者等が日常的な地域生活を送るエリアとして、地域センターと同一の１３地区を日常生活圏域として位置づけ、この１３地区を基本に、区内２０カ所の在宅介護支援センターを中心とした在宅介護支援システムを構築しております。介護保険制度における申請、相談、アセスメント、ケアプランの作成、サービス提供の一連のプロセスを適切に行っております。\nまた、介護保険制度改正により、平成２７年度から要支援者の介護予防訪問介護および介護予防通所介護事業が地域支援事業の介護予防日常生活支援総合事業として位置づけられました。区の総合事業への円滑な移行実施とともに、今後も引き続き、予防から介護に至る継続的で一貫性のあるマネージメントを通じて、介護予防の推進と、在宅介護支援システムの一層の強化、充実を図ってまいります。\n次に、９ページをご覧ください。こちらの表は、平成２４年度から平成２６年度までの３年間の介護保険給付件数の推移でございます。\n次のページをご覧ください。３、介護保険料賦課徴収事務でございます。第１号被保険者数は、平成２７年４月３０日現在、６５歳以上の人、外国人、住所地特例の人を含めますと７万９,５８２人でございます。平成２７年４月３０日現在の第１号被保険者の月額保険料と段階人数は、こちらの表になっておりますけれども、第１段階と第２段階の保険料率につきましては、先般、臨時会において議決をいただき、０.４％になります。また、第六期の基準額は５,３００円でございます。\n次のページをご覧ください。要介護高齢者等のための事業について、ご説明いたします。\n１、在宅介護支援センターでございますけれども、在宅介護を行っている家族が身近なところで介護支援相談員に相談できる場として、２０カ所の在宅介護支援センターを設置しております。具体的な内容としては、相談と、必要なサービスの調整、手続の代行、福祉機器の紹介や住宅改修相談、要介護認定調査、基本チェックリストの実施、居宅サービス計画、いわゆるケアプランの作成等を行っております。相談の実績については、１２ページから１４ページに記載のとおりでございます。\n次に、１５ページをお開きください。介護保険サービスの利用にあたっては、介護支援専門員と相談のうえ作成したケアプランに基づき、サービスを利用いたします。利用者料金は費用の１割ですけれども、平成２７年８月からは、一定所得以上の人は２割になります。\nはじめに、２、家庭を訪問してのサービスでございます。まず、(1)、訪問介護（ホームヘルプサービス）でございますけれども、ホームヘルパーが居宅を訪問し、入浴、排泄、食事等の身体介護や調理、洗濯などの生活援助を行います。\n次に、１６ページをお開きください。(2)、訪問看護サービスでございます。こちらは、訪問看護ステーション等から看護師等が家庭を訪問し、主治医の指示による看護や病状観察、療養上の世話などを行います。\n(3)、訪問リハビリテーションでございます。こちらは、訪問看護ステーション等から、理学療法士等が訪問し、主治医の指示による機能訓練および介護者への指導を行います。\n次のページになります、(4)、訪問入浴介護サービスは、入浴が困難な在宅の要介護者等に、給湯、浴槽等の機器を登載した巡回入浴車を派遣し、入浴の介護を行い、身体の清潔の保持、心身機能の維持を図るものでございます。\n次に、１８ページをお開きください。３、施設を利用してのサービスでございます。まず、(1)、通所介護（デイサービス）でございますけれども、通所介護施設で、食事、入浴などの日常生活の支援や生活能力向上のための支援を行います。また、食事サービスとして、身体上の障害等により通所介護を利用できない要介護高齢者等に対して、在宅サービスセンターで調理した食事を家庭に配食しております。\n次に、ふれあいデイホームでございますけれども、こちらは、身近な地域で、週１～２回、高齢者と園児のふれあいを目的に小規模在宅サービスセンター事業を、五反田保育園、ふれあいデイホームで実施し、運営を福栄会に委託しております。\n在宅サービスセンター利用実績は、隣のページのようになっております。\n次に、２０ページをお開きください。(2)、リハビリサービスでございます。通所リハビリテーションはケアセンター南大井で実施しております。心身の機能が低下した要介護者等を対象に、通所により必要な訓練を行うものでございます。介護保険市町村特別給付事業として、これまで行っておりました「身近でリハビリ」と、隣のページの「水中運動」につきましては、平成２７年度から法改正により、それぞれ一般介護総合事業の「身近でトレーニング」と「水中トレーニング」に移行いたしました。\n次に、２２ページをお開きください。(3)、短期入所生活（療養）介護（ショートステイ）でございます。要介護者が家族の疾病、冠婚葬祭、または休養等のために介護を受けられない場合、特別養護老人ホーム等で短期間入所するものでございます。\n次のページの４、地域密着型サービスでございます。こちらは、身近な地域ごとにサービス拠点を整備し、住み慣れた地域で生活を継続できるよう、主に要介護１から５の方に対し、地域の実情に応じたサービスを提供しております。\nまず、(1)、小規模多機能型居宅介護は、通いを中心に利用者の選択に応じて訪問サービスや泊まりのサービスを組み合わせたサービス提供をするものでございます。\n次に、(2)、認知症対応型通所介護（認知症デイサービス）は、認知症の方を対象に、少人数でできるだけ家庭に近い環境の中で、一人ひとりの気持ちや行動を尊重したケアを行い、家事等、有する能力に応じた役割を担うことや趣味活動を行いながら日中を過ごすことにより、本人の心身機能の向上と、家族の介護負担の軽減を図るものでございます。\n２４ページをお開きください。下のほうになります、(3)、認知症対応型共同生活介護（認知症グループホーム）でございます。認知症の方が、家庭的な雰囲気で、本人の能力に応じた役割を担うような、共同生活をしながら認知症症状の進行を防止し、生活機能の維持向上を図っているものでございます。\n次のページの(4)、夜間対応型訪問介護（ホームヘルプサービス）は、要介護１以上の人を対象にしており、あらかじめ自宅にケアコール端末を設置し、夜間に看護師やケアマネージャーなどの専用オペレーターが利用者からの通報を受け、必要に応じて、介護スタッフが速やかに駆けつけて対応するものでございます。こちらは看護師の訪問はありません。\n次に、(5)、２４時間定期巡回随時対応型訪問介護看護（訪問看護連携型）は、要介護１以上を対象としております。１日数回、短時間の身体介護を中心とした定期巡回による訪問介護を行うものでございます。また、利用者からの通報を２４時間受け付ける体制を整備しております。こちらにつきましては、必要に応じて看護、介護、両方ともスタッフが迅速に駆けつけて対応をする随時対応サービスを行っております。\n２６ページをお開きください。５、市町村特別給付でございます。こちらは、介護保険法で定められた介護給付とは別に、第１号被保険者の保険料を財源に品川区独自で実施している事業でございます。\n一つ目としては、要支援者を対象にした夜間対応サービス特別給付、二つ目としては、通院等外出介助サービス特別給付、三つ目としては、地域密着型ケアホームサービス提供費特別給付でございます。\n次に、２８ページをお開きください。６、福祉用具や住宅改修などでございます。まず、(1)、福祉用具の貸与でございますけれども、在宅の要介護者等を対象に、日常生活上の便宜を図るため、福祉用具として車いすや特殊寝台、手すり等の貸与を行うものでございます。\n次の(2)、福祉用具購入費の支給は、在宅要介護者等が入浴、または排泄の用に使用する福祉用具を購入したときに、購入費を支給するものでございます。年１０万円が限度で、利用者負担はその１割、平成２７年８月からは、一定所得の人は２割になります。\n次のページの(3)、住宅改修費の支給は、要介護者等で住宅の改修が必要と認められた方に対して、手すりの設置や段差の解消等の改修についての工事費を、２０万円を限度に支給するものでございます。利用者の負担は工事費の１割、また、同じく平成２７年８月からは、一定以上の所得のある方は費用の２割になります。\n次に、その下になります、(4)、高齢者自立支援住宅改修給付事業でございます。こちらは、区の一般施策事業になります。６５歳以上の在宅高齢者の日常生活を支援するため、状態像に即した居宅内の改修施工費に対し、改修費を支給するものでございます。\n次のページをお開きください。対象限度額・利用料金が表になっております。自立支援住宅改修の住宅改修予防給付は、対象者は介護保険の認定が非該当と認定された６５歳以上の高齢者でございます。住宅設備改修給付は、要介護、要支援と判断された６５歳以上の高齢者で、いずれも所得制限があります。住宅設備改修給付は、前のページでご説明いたしました介護保険の住宅改修費の支給が優先されるような仕組みになっております。\n次のページをご覧ください。７、在宅療養推進事業でございます。(1)、医療ショートステイ事業は、在宅療養者で、ショートステイの利用が必要ではあるのですけれども、医療処置のため特別養護老人ホームでのショートステイ利用が困難な場合に、区が指定した医療機関に一時的に入院することで、在宅療養の継続を支援するものでございます。\n次に、３２ページをお開きください。(2)、医療と福祉の連携のための学習会・意見交換会でございます。医師会、歯科医師会、薬剤師会、訪問看護ステーション、ケアマネージャー等、在宅療養に係わる支援者が学習と意見交換を通じて、医療と福祉に関する情報を共有し、顔の見える関係を持って、円滑な連携を進めているところでございます。\n隣のページになります。次は、８、施設サービスでございます。(1)、特別養護老人ホーム（介護老人福祉施設）は、日常生活の全般にわたって、常時介護が必要で、在宅での生活が困難な要介護者に日常生活上の必要なサービスを提供いたします。対象は、今年の４月から、要介護３以上の方が原則になっておりますけれども、やむを得ない事情により、特別養護老人ホーム以外の生活が著しく困難であると認められる要介護１、２の方につきましても、入所することが可能でございます。\n昨年１２月に杜松小学校特別養護老人ホームが開設いたしまして、現在、区内で９カ所、定員６８２人でございます。そのほか、区外８施設、７５床のベッドを確保しているところでございます。\n次に、３４ページをお開きください。(2)、介護老人保健施設でございます。ケアセンター南大井において、介護が必要で病状が比較的安定している高齢者を対象に、看護、リハビリテーションなどの医療ケアと介護などの生活サービスを提供し、在宅生活への復帰を支援しているところでございます。\n少し飛びまして、４６ページをお開きください。１１、保険者としての事業について、ご説明いたします。まず、(1)、要介護認定でございますけれども、介護保険サービスを利用するために、介護認定審査会で介護サービスの必要度を判定するものでございます。一次判定結果と特記事項および主治医意見書に基づいて、審査・判定を行っているところです。要介護度（要支援）別審査件数は、下の表のとおりになっております。\n４８ページをお開きください。(2)、介護保険制度推進委員会でございます。こちらは、介護保険事業の実施状況の確認や評価を行うことにより、制度運営の透明性を確保し、介護保険制度の円滑、かつ公正な運営を図るために設置しております。実績は、以下のとおりになっております。\n次に、５２ページをお開きください。(4)、高齢者虐待防止ネットワーク事業でございます。地域包括支援センターの役割の一つとして、高齢者虐待防止に向けたネットワークの構築と、早期発見対応の強化を図っております。高齢者虐待予防研修会は、今年２月１２日に開催いたしました。また、しながわ見守りホットラインの設置および緊急一時保護の施設を確保しております。虐待対応件数は、以下のとおりでございます。\n次のページになります、(5)、特別養護老人ホーム入所調整でございます。特別養護老人ホームへの入所の公平性を確保するために、第三者の委員等を含めた特別養護老人ホーム入所調整会議を設けて、一定の入所基準により入所優先順位を、客観的、公平に審査しております。\n入所調整基準ですけれども、要介護度を基本に、本人の認定、在宅介護状況、介護の困難性の各項目について総合的に評価をいたします。入所申し込みは、年２回で、８月末と２月末が締め切りになっております。\n次に、５４ページをお開きください。(6)、認知症高齢者の支援とケアの充実では、認知症ケア専門研修、認知症サポーター養成事業等を実施しております。平成２６年度からは、認知症サポーターレベルアップ事業を開始し、認知症サポーター養成講座を受けた人が、今度、サポーターとして地域で活動するための機会や仕組みをつくるために事業を実施しております。\nまた、認知症早期発見・早期診断推進事業は、保健師３名が区の認知症コーディネーターになっておりますけれども、保健師と、荏原病院の認知症疾患医療センターの認知症アウトリーチチームが協働して、認知症の疑いのある人を把握・訪問して、医療・介護サービスにつなげるような事業を進めているところでございます。\n次のページの(7)、ケアマネジメント支援事業は、ケアマネージャー等の専門性の向上を支援することにより、介護給付の適正化を図るものでございます。具体的には、ケアプランサポート研修やリハビリ訪問相談を行っております。\n５６ページになりますけれども、認知症専門チームでは、保健・医療・福祉の担当者が連携して、認知症高齢者の特質に着目したマネージメントやケアの能力の向上を支援する目的で、認知症専門カンファレンスや認知症専門集中講座を実施しております。\nまた口腔ケア研修は、歯科医師会にご協力をいただき、品川福祉カレッジ専門コースとして実施しております。\n次のページの(8)、品川介護福祉専門学校修学資金貸付事業は、品川介護福祉専門学校の生徒を対象に、修学資金の貸付制度を設け、区内の指定介護施設への福祉人材の確保を図ることを目的にしております。卒業後、区内の指定福祉施設で３年以上勤務した場合、貸付金の返済が免除になります。\n５８ページをお開きください。品川介護福祉専門学校の機能を活用して、品川区の福祉人材の育成を図るため、(9)、品川福祉カレッジや、次のページにある、(10)、社会福祉士養成コース受講助成を実施しております。\n次に、６０ページをお開きください。(11)、品川区民間社会福祉施設職員住宅提供事業や介護職員の初任者研修の受講費を助成する、次のページにある(12)、訪問介護員の雇用促進助成事業、また６２ページになりますけれども、(13)、福祉人材確保・定着事業といった事業を行うことによって、優れた人材の確保と定着を図っております。\n６３ページになります。(14)、要介護度改善ケア奨励事業は、基準時に対象施設の入所者について、当該年度の前年度１年間において要介護度が軽減された場合は、その要介護度の軽減に資するサービス提供を評価し、１段階改善するごとに、１カ月２万円の奨励金を１２カ月を限度に支給するものでございます。実績については、この下に書いてある表のとおりとなっております。\n次に、６４ページをお開きください。１２、在宅介護者研修事業でございます。長年、要介護高齢者等を介護している家族を対象に、心労をねぎらい、介護に必要な技術知識を習得するための講座や、介護者同士の情報交換の場を設け、介護者の負担軽減を図っております。(1)、在宅介護支援研修事業や(2)、家族介護者教室、また、(3)、家族介護者応援講座を実施しているところでございます。\n次に、６７ページをお開きください。(2)、徘徊高齢者探索システム事業でございます。認知症で徘徊行為のある高齢者を在宅で介護する家族に対し、ＧＰＳ端末機を貸与し、徘徊高齢者の早期発見と、安全の確保に役立てているものでございます。\n次に、６８ページをお開きください。(3)、自動消火装置でございます。こちちは、火災や爆発の事故を未然に防止するため、おおむね６５歳以上の認知症高齢者で、ひとり暮らし、または高齢者のみの世帯を対象に、自動消火装置、ガス安全システム、電磁調理器を給付するものでございます。\n次に、７２ページをお開きください。(7)、高齢者熱中症等予防対策事業は、夏季における在宅高齢者の熱中症予防のための普及啓発や戸別訪問支援を実施しております。また、区内のシルバーセンターの施設の一部を在宅高齢者の避暑拠点として活動し、熱中症予防に対応するものでございます。\n次に、７９ページをお開きください。６、養護老人ホーム入所措置でございます。こちらは、環境上の理由や経済的な理由において、在宅で生活することが困難な高齢者を措置により入所させ、養護する施設で、実績は以下のとおりでございます。"},{"i":45,"speaker":"松山高齢者地域支援課長","text":"それでは、私から、高齢者地域支援課の事務事業概要について、説明させていただきます。１ページをお開きください。体制は２係と２担当主査制、１７名で構成しております。事務分掌は、３ページに記載のあるとおりです。\n恐れ入りますが、３５ページをお開きください。９、介護予防・日常生活支援総合事業（介護予防・生活支援サービス）でございます。平成２６年の介護保険制度改正により、本年４月より、要支援高齢者の予防訪問介護と予防通所介護は、区が実施する地域支援事業に位置づけられました。要介護認定を受けていなくても、要支援相当と見込まれる場合で、このサービスを利用することで、在宅生活が可能となる場合は、この総合事業対象者としてサービスを利用することが可能になります。いずれも、在宅介護支援センターによる介護予防ケアマネジメントによりサービスを提供するものでございます。\n区では、これまで予防訪問介護と、予防通所介護を利用していた要支援者がサービスを継続利用できることを基本としまして、総合事業への円滑な移行を進めてまいりました。総合事業につきましては、次回の厚生委員会で、改めて、ご報告させていただきます。\n目的は、要介護状態になることの予防、軽減のほか、地域におきまして、日常生活の自立を支援するものでございます。\n対象者は、要支援者と在宅介護支援センターが実施する基本チェックリストにより判定された総合事業対象者でございます。\nサービスの種類および内容でございます。1)、予防訪問事業でございます、訪問型サービスになります。これまでの全国一律の予防給付の訪問介護から、総合事業として区が主体となって実施することになりました。ホームヘルパーが居宅を訪問し、食事・入浴等の身体介護と、掃除、洗濯などの生活援助を行っております。\n2)、生活機能向上支援訪問事業でございます。恐れ入りますが、７４ページをお開きください。平成２６年度までは、３、高齢者生活支援事業として、高齢者福祉課が行っておりました。ケアマネージャーが居宅を訪問し、アセスメントにより生活機能向上の支援が必要とされるひとり暮らしの高齢者や高齢者世帯にヘルパーを派遣して、生活援助を行うものでございます。介護予防の観点から、本人のできることは、できるだけ本人が行うように支援するものでございます。平成２７年度より総合事業になり、高齢者地域支援課へ移行いたしました。\n恐れ入りますが、再び３５ページにお戻りください。1)の身体介護サービスを行う事業と、身体介護を除く生活援助を行う2)の事業と、サービス内容を明確にしまして、それぞれのサービスに準じた単価を設定いたしました。\n次に、3)、管理栄養士派遣による栄養改善事業でございます。栄養改善が必要な方に対して、管理栄養士が居宅を訪問し、食事状況や栄養状態を確認し、献立作成などの支援をしております。\nその下、(2)、予防通所事業、通所型のサービスでございます。これにおきましても、予防訪問事業と同様に、総合事業として、区が主体となって実施することになりました。デイサービス等で、日常生活上の支援や機能訓練を行うものでございます。\n2)、いきいき活動支援プログラムでございます。1)の予防通所事業から引き続き一体的に行うプログラムでございまして、平成２７年度より創設いたしました。事業者がそれぞれの特性を生かし、自立支援や介護予防の効果が期待できるような提案を区に届け出ていただき、区が承認することで実施する事業でございます。\n3)、はつらつ健康教室でございます。恐れ入りますが、４０ページをお開きください。平成２６年度までは二次予防事業対象者の介護予防事業として高齢者福祉課の所管でしたが、平成２７年度からは総合事業として高齢者地域支援課に移行いたしました。７５歳以上の介護や支援が必要となるおそれのある人を対象に、体力や口腔機能の向上、低栄養の予防、認知機能の維持改善のため、複合型プログラムを実施するものでございます。\nそれでは、３６ページをお開きください。１０、一般介護予防事業でございます。(1)、いきいき脳の健康教室でございます。こちらは、東北大学の川島教授の研究成果をもとに、音読と計算を中心とする教材を使った学習を、学習サポーターがコミュニケーションを取りながら行うことにより、認知症を予防するものでございます。\nその下の(2)、在宅サービスセンター等施設を利用した介護予防事業でございます。1)、マシンでトレーニングでございます。在宅サービスセンターで、高齢者専用のマシンを使った筋力トレーニングを行うことにより、日常生活に必要な体力や運動習慣をつくるものでございます。\n３７ページ、2)、身近でトレーニングでございます。在宅サービスセンターで椅子やタオルなど、身近なものを使って行う筋力トレーニングで、自宅ででもできる方法を提供しまして、体力をつくるものでございます。\nその下の3)、水中トレーニングでございます。ケアセンター南大井の水中運動浴槽を使用しまして、水の特性を生かした筋力トレーニングやバランス運動を行っております。\n次の、３８ページをお開きください。4)、予防ミニデイでございます。デイサービスセンターに通って、運動や食事、趣味活動を通して交流を行うことで、閉じこもり予防をしております。\n5)につきまして、高齢者福祉課の所管でございます。\n次の３９ページ、6)、介護予防体操でございます。柔道整復師によるストレッチを基本とした体操を行い、柔軟性や筋力アップをさせることで転倒予防を行っております。\n次に、４１ページをご覧ください。(3)、地域貢献ポイント事業でございます。社会福祉協議会へ委託して、高齢者向けのボランティア活動への参加者にポイントをつけまして、区内商品券と交換、または社会福祉事業に寄付するなどの社会貢献活動につながることで、高齢者の介護支援ボランティア活動の普及を図るものでございます。\nその下の、(4)、わくわくクッキング（地域活動連携型介護予防事業）でございます。ＮＰＯ法人と連携し、献立づくりから商店街の食材の買い物、調理実習と、管理栄養士による講習会を通して、閉じこもり、認知症、低栄養の予防を図っております。\n次の４２ページ、(5)、いきいき筋力向上トレーニングでございます。高齢者専用のマシンを使ったトレーニングやウォーキングを行い、自主的なトレーニング習慣を身につけるものでございます。\n４３ページの下、(6)、いきいきうんどう教室事業でございます。屋外に設置しました健康遊具を使って、つまずかない、ふらつかないなどの運動を行います。教室以外でも自主的に行うよう誘導することにより、運動の習慣化を図るものでございます。運動指導員の養成も行っております。\n次の４４ページ、(7)、シニアのための男の手料理教室でございます。料理初心者に、ふだんの生活に生かせるような買い物、調理、後片付けの実習を行うことで、ひとり暮らしの方の自炊習慣のサポートと、仲間づくり行っております。\n４５ページ、(8)、高齢者外出習慣化事業でございます。栄養のバランスの取れた食事を提供するともに閉じこもりがちな高齢者が地域で顔見知りをつくり、外出習慣を身につけることを目指しております。本年度より、身近なお店として品川区商店連合会と連携し、地域のお店を会場として行っております。\n恐れ入りますが、８０ページをお開きください。【４】、生きがいづくりと社会参加促進事業でございます。１、高齢者お祝い事業。(1)、シルバー成年式でございます。７０歳を向かえた方に新たな気持ちで高齢社会に臨むための契機としていただくために、きゅりあんで記念式典、催しものなどでお祝いをするものでございます。本年は９月１２日を予定してございます。\n８１ページに２、高齢者社会参加プログラム促進事業でございます。平成１３年度に策定した高齢者社会参加プログラムに基づきまして、高齢者クラブやヤングシニア等によるボランティア活動への支援、高齢者の社会参加の促進を図っております。この中で、区政への協力や社会貢献の意思のある方々、主に団塊の世代の方々に働きかけまして、今後の地域のリーダーの育成を進めてございます。\n８２ページをお開きください。３、高齢者の趣味・生きがいづくり事業でございます。(1)、高齢者作品展、その下の(2)、シルバーダンスパーティ、次のページの(3)、高齢者グラウンドゴルフ大会、その下の(4)、いきいきカラオケ広場、そして次の８４ページの(5)、いきいき健康マージャン広場、その下の(6)、高齢者輪投げ大会、そして８５ページの(7)、高齢者福祉団体登録まで、七つの健康仲間づくり事業を実施しております。\nその下、４、シルバーパス交付事務でございます。東京都の事業で、東京バス協会が受託しているものでございます。\n８６ページをお開きください。５、高齢者クラブ等支援事業でございます。(1)、花づくり助成事業は、高齢者クラブの花づくりの活動に必要な経費の一部を助成しております。\nその下の(2)、高齢者クラブ運営助成は、高齢者クラブと高齢者クラブ連合会に運営経費を助成いたしまして、ボランティアや緑化推進などの運営を支援するものでございます。\n８７ページ、６、おとしよりと子どものふれあい事業でございます。高齢者と子どもたちが一緒に事業を行うことで、世代間の交流を図るものでございます。\n８８ページをお開きください。７、シルバーセンターの運営でございます。シルバーセンターで、地域の高齢者に入浴やマッサージサービスを提供するとともに、憩いの場、趣味、ふれあいの場としてご利用いただいております。現在、改築中の平塚橋と大崎のシルバーセンターは、多世代交流ができる施設として、来年、開設予定でございます。\nその下、８、法人に対する助成（西大井いきいきセンター運営助成）でございます。平成２１年３月より、旧品川区立西大井シルバーセンターの事業を継承しまして、民設民営の西大井いきいきセンターとなりました。運営主体のこうほうえんに対して助成するものでございます。\n次の８９ページには、シルバーセンター、いきいきセンターの施設、事業一覧を、そして、次の９０ページには、年度別の利用者数の一覧を掲載してございます。\n次の９１ページ、【５】、高齢者住宅対策でございます。立ち退き等で住宅に困窮している高齢者に対しまして、住まいの確保や居住水準の改善を図るものでございます。\nその下の１、高齢者住宅運営、(1)、高齢者住宅運営でございます。区内１０カ所の高齢者住宅を運営いたしまして、お部屋が空いたときに、随時、ご入居をいただいております。\n９２ページでございます、２、高齢者住宅対策事業、(1)、住宅のあっ旋でございますが、公益法人「東京都宅地建物取引業協会品川支部」のご協力をいただきまして、高齢者に住宅をあっ旋し、礼金、保証料などを助成しております。\n９３ページ、(2)、家具転倒防止対策助成でございます。震災に供え、高齢者や障害者の世帯に家具転倒防止器具の購入および取付けの助成を行うものでございます。\n９４ページでございます。３、高齢者向け優良賃貸住宅家賃助成でございます。ケアホーム西大井、コムニカ、区立大井林町高齢者住宅につきまして、家賃の一部を助成することにより、入居者の負担軽減を図っております。\nその下の４、サービス付高齢者住宅整備助成・促進でございます。介護や医療と連携し、ケアの資格者による見守りサービスがついた高齢者向け住宅の整備者に対しまして、整備費の一部を助成しております。下の実績欄の助成型ｃａｒｎａ五反田は、区が整備費の一部を助成しまして、本年２月に開設いたしました。その下の同意型は、東京都から紹介される民間事業者による住宅整備案に対しまして、区が整備基準に基づいて同意することで、東京都の補助金が交付され、整備を促進するものでございます。\n区の同意により、Ｃアミーユ西大井が５月に開設し、ケアホスピタル西小山が７月開設予定でございます。\n次の９５ページ、５、サービス付高齢者住宅家賃助成でございます。前のページのサービス付高齢者住宅のうち、区が助成した住宅について、家賃の一部を助成し、入居者の負担軽減を図るものでございます。次の９６ページには、高齢者住宅一覧を掲載してございます。"},{"i":46,"speaker":"中山障害者福祉課長","text":"私からは、障害者福祉課の事務事業概要について、障害者福祉編に基づきご説明いたします。\nこちらの１ページをご覧ください。はじめに組織および職員数ですが、障害者福祉課は、二つの係と四つの担当主査で構成されています。職員の総数は３１人になります。それぞれの事務分掌につきましては、この下に記載のとおりでございます。\n次に、２ページから４ページにかけまして、品川区障害者計画・障害福祉計画を抜粋しております。昨年度、策定委員会を設置いたしまして、この二つの計画を策定いたしました。障害者計画は平成２７年度から３５年度の長期計画で、基本方針や施策の方向など、区の障害者施策の目指す姿をあらわしたものでございます。\n一方、障害福祉計画は、平成２７年度から平成２９年度までの短期計画で、具体的に推進するため、数値目標を定めた計画になっております。\nそれでは、おめくりいただきまして、４ページをご覧ください。(5)、施策の方向と展開のところに、自分らしく、あなたらしく、共感と共生の社会という基本理念のもと、三つの基本方針のもとに９本の施策の柱を設定し、今年度から、この計画に基づき障害者の施策を推進してまいります。\n次に、６ページをご覧ください。【１】相談・施設でございます。まず、１、心身障害者福祉相談は、区で受け付けた相談の状況になっております。平成２６年度は身体障害者の相談が８,５０５件、知的障害者相談件数が６４６件となっております。\n２、基幹相談支援センターは、障害者福祉課に設置しているもので、人材育成や虐待の対応等を行っております。\n次の３、品川区拠点障害者相談支援センターになりますが、こちらは区内に３カ所あります。まず、心身障害者福祉会館にあります(1)、品川区障害者生活支援センター、それから、７ページの(2)、福栄会障害者相談支援センター、こちらは二つとも身体障害と知的障害の相談支援と、支援計画の作成をしているところになります。\n精神障害の方は、(3)、精神障害者地域生活支援センター「たいむ」というところで相談支援を行っているところでございます。\n８ページにまいりまして、障害者の就労の相談になりますが、４、品川区障害者就労支援センターにおいて、障害者の民間事業所等への就労機会の拡大と、定着化が図られるよう、訓練から就職後のジョブコーチ支援まで、一体的な運営を行っているところでございます。\nまた、５、身体障害者・知的障害者・精神障害者相談員による相談は、地域の民間の方々に、品川区長が業務を委嘱して行っているものです。任期は２年で、現在、２５人の相談員が活動されています。こちらは、当事者の方、あるいは親の会の方が相談に乗ることで、区や支援センターで相談できない身近な気持ちのところの相談を行っているところでございます。\n次に、１０ページをご覧ください。６、区立の障害者施設になります。まず最初に、(1)、品川区立心身障害者福祉会館は、機能訓練、生活訓練、生活介護、地域活動支援センター「逢（あえる）」を運営しています。指定管理者は、品川総合福祉センターになっています。\n１１ページにまいりまして、(2)、品川区重症心身障害者通所事業ピッコロ（Ｐｉｃｃｏｌｏ）。こちらは在宅の重症心身障害者が、家族とともに地域で暮らせるよう、平成２４年６月に開設いたしました。重症心身障害者の卒後対策として、生活介護と、理学療法、摂食指導、スヌーズレン等を実施しています。また、在宅で重症心身障害者の子育てをしている保護者のレスパイト事業もあわせて行っています。区の直営になっておりますが、社会福祉法人全国重症心身障害者を守る会に委託をしているところです。\n(3)、品川区立かがやき園になります。こちちは、知的障害者の施設入所支援と、生活介護事業、短期入所を行っています。指定管理者は福栄会です。\nおめくりいただきまして、１２ページにまいりまして、(4)、品川区立西大井福祉園になります。こちらは、知的障害者を対象に就労継続支援Ｂ型と、生活介護事業を行っている通所型の事業所になります。指定管理者は福栄会になります。\nその下、(5)、品川区立発達障害者支援施設「ぷらーす」。こちちは、発達障害者の成人期支援の拠点として、平成２６年４月に開設いたしました。発達障害者の特性を活かした就労継続支援Ａ型とＢ型のほか、思春期サポート事業や成人期支援事業の運営など、思春期から成人期への一貫した支援の構築を目指しているところでございます。指定管理者は、社会福祉法人げんきになります。\n次のページにまいりまして、(6)、品川区立知的障害者グループホーム・ケアホームといたしまして、現在、３カ所ございます。北品川つばさの家と、西大井つばさの家、そして、今、ご説明いたしましたぷらーすと併設いたしまして、上大崎つばさの家があります。いずれも知的障害の方を対象としたグループホームとなっております。\n１４ページにまいりまして、(7)、品川区立品川児童学園（児童発達支援センター）になります。こちらは、児童発達支援センターといたしまして、品川区子ども発達相談室と、障害者通所支援、発達障害児を対象とした療育事業「コンパス」を実施しています。また、放課後等デイサービスや保育所等訪問支援も行っております。こちらは、指定管理者は福栄会になっております。\n次に、１５ページにまいりまして、【２】、手帳の交付になります。１、身体障害者手帳は、身体障害者（児）が施設利用など各種援護を受けるために必要な手帳になっています。平成２７年４月１日現在の手帳所持者数は９,６２８人となっております。\nまた、愛の手帳は、知的障害者（児）が各種援護を受けるために必要な手帳になります。申請先が、１８歳未満は児童相談所、１８歳以上は、東京都心身障害者福祉センターになります。平成２７年４月１日現在の手帳所持者数は１,７４２人になっており、いずれも微増の傾向にあります。\n次に、１６ページをご覧ください。【３】、障害者総合支援法になりますが、平成２５年４月１日に法律の名称変更とともに、障害者の範囲に、制度の谷間を埋めるべく難病等が加わっております。障害者福祉サービスの体系といたしましては、１７ページになりますが、自立支援給付として介護給付、訓練等給付、自立支援医療、補装具、この四つがございます。このほか、点線の枠外になりますが、地域生活支援事業といたしまして、相談支援や、手話通訳などの意思疎通支援などがございます。\nこれらのサービスを受けるためには、区に申請を行い、支給決定を受けることが必要になります。まず、1)、障害程度区分になりますが、介護給付を利用する場合には、福祉サービスの必要性を総合的に判断するために、全国共通の障害支援区分の認定を行うことが必要になります。こちらの区分は１から６まであります。この障害支援区分の認定の流れは、１８ページの図のとおりとなっております。こちらの認定が終わりましたら、(2)のとおり、サービス利用計画の策定、そして支給決定を行い、実際にサービスをご利用いただくということになっております。\n次に、５、地域自立支援協議会ですが、相談事業をはじめ、地域の関係機関が連携、協議する場として設置しているものです。平成２６年度は２回開催いたしました。今年度から、自立支援協議会のメンバーを拡大し、障害福祉計画の推進に向けた体制を整えてまいります。\n障害者総合支援法の対象となる具体的なサービスは、１９ページから２０ページのとおりとなっております。\n実際の給付の実績になりますが、２１ページをご覧ください。まず、１、介護給付ですが、(1)、居宅介護。こちらは、居宅において入浴や排泄、食事の介護、調理、掃除など、家事の援助を行うものです。\nその下の(2)、重度訪問介護は、重度の肢体不自由者であって常時の介護を必要とする障害者に対して、居宅における介護のほか、外出時における移動中の介護などを総合的に行うサービスになっております。\n２２ページをご覧ください。(3)、同行援護になります。こちらは、視覚障害の方に対して、外出時の移動の安全確保と、情報提供等の支援を合わせて行うものになります。\nその下の(4)、短期入所（ショートステイ）になります。こちらは、障害者等の介護が一時的に行えないときに、施設などの短期入所により、入浴、排泄、食事等の必要な支援を行うものです。\n２３ページにまいりまして、(6)、その他の施設系サービスといたしましては、療養介護、生活介護、施設入所支援などがあります。\n次に、その下の２、訓練等給付になります。こちらでは、(1)の共同生活援助（グループホーム）になりますが、平成２６年４月に法改正がありまして、ケアホームと一元化されたところです。\n(2)、その他の施設系サービスといたしましては、こちらに記載のとおり、自立訓練や就労移行支援、就労継続支援などがございます。\n続きまして、２４ページをご覧ください。３、障害者施設利用者数になります。施設入所者の日中活動の場としては、生活介護がほとんどを占めています。また、在宅者は、生活介護と就労継続支援Ｂ型が多くなっている状況でございます。\n２５ページにまいりまして、４、補装具費の支給になりますが、身体的障害のある方が、失われた機能を補って、日常生活や就業活動を容易にするためのものとなります。具体的な品目につきましては、２６ページをご参照いただければと思います。\n２７ページにまいります。５、地域生活支援事業になります。(1)、移動支援事業ですが、こちらは、屋外での移動が困難な障害者の方に対して、外出のための支援を行うことで、障害者の社会参加を促すものです。\n(2)、障害者（児）巡回入浴サービスになります。こちらは、在宅での入浴が困難な方、重たい心身障害者の方に対して巡回入浴車を派遣し、衛生の確保をするものです。今年度から、週２回に増回しているところでございます。\n続きまして、２８ページをご覧ください。(3)、日常生活用具の給付になります。品目や実績につきましては、この下の表のとおりでございます。\nまた、(4)、住宅設備改善費の給付や、２９ページの(5)、障害者緊急通報システム等の実績は、以下のとおりでございます。\n少し飛びまして、３１ページにまいりまして、中段のところに、(10)、日中一時支援事業になります。こちらは、特別支援学校等に通学する障害児の家族の就労支援や一時休息のために、放課後や夏休みなどの長期休暇中の活動の場の提供ということになっております。現在、にじのひろばは荏原と八潮の２カ所で運営しているところでございます。\nおめくりいただきまして、３２ページをご覧ください。【５】、児童福祉法に位置づけられるサービスでございます。未就学児の療育を行う児童発達支援と、医療型児童発達支援、そして、修学児童の療育の場として、放課後等デイサービスがございます。また、保育所等を訪問して、専門的な支援を行う保育所等訪問支援もございます。\n【６】、児童福祉法による給付・支援の実績は、３３ページのとおりになりますが、平成２４年度から平成２６年度にかけて、いずれも大きく実績が伸びているところでございます。民間の療育機関も増えており、今後も給付の伸びが予測されているところでございます。\n次に、３４ページにまいりまして、【７】、各種支援事業になります。１、障害者福祉手当には、国の制度である特別障害者手当、それから、障害児福祉手当、経過措置としての福祉手当がございます。東京都の制度といたしましては、３５ページになりますが、(2)、重度心身障害者手当がございます。また、区の制度といたしまして、その下、(3)、障害者福祉手当、こちらが一種と二種がございます。\nおめくりいただきまして、３７ページになります。２、医療費助成ですけれども、(1)、医療費の助成は、東京都のマル障の制度になります。\nまた、その下、(2)、自立支援医療（更生医療）の給付は、障害者総合支援法に基づく給付になります。\n３８ページにまいりまして、３、日常生活の支援になりますが、(1)、障害者福祉電話をはじめとしまして、(2)、杖の交付、そして、３９ページの(3)、車いすの貸出しなど、さまざまな事業を行っているところでございます。\n４０ページをご覧いただきまして、(6)、障害者の成年後見制度利用支援事業になりますが、こちらは、後見人の選定が必要な知的障害者および精神障害者等について、品川成年後見センターの法人後見制度等を活用して実施をしているところでございます。\nその下、(7)、障害者虐待防止支援事業ですが、平成２４年１０月に障害者虐待防止法が施行されたことを受けまして、障害者福祉課に障害者虐待防止センター機能を設置いたしました。虐待の防止、早期発見、早期対応、ならびに養護者支援ということで行っているところでございます。平成２６年度の相談件数、通告件数は１８件でした。\n４１ページにまいりまして、(8)、第三者評価受審支援になります。こちらは、障害福祉サービスの質の向上を図るため、東京都福祉サービス第三者評価受審を支援しているものでございます。\n(9)、重度脳性麻痺者介護事業は、東京都の補助事業になります。\nその下、(10)、精神障害者地域生活安定化支援事業になりますが、こちらは、精神障害者が地域で安定して暮らしていくために、医療の中断防止、あるいは社会参加、通院の見守り支援を行っているものでございます。あわせて、精神障害者の交流の場も運営していただいております。\n４２ページにまいりまして、４、社会参加への支援といたしましては、(1)、福祉タクシー利用券の交付をはじめといたしまして、(2)、自動車燃料費助成券の交付、あるいは、４３ページにまいりまして、(3)、リフト・寝台付福祉タクシー、(4)、福祉車両助成事業など、記載のとおりでございます。\n続きまして、４４ページをごらんください。(5)、知的障害者地域生活サポート２４事業になります。こちらは、グループホームや地域に単身で生活している知的障害者の相談や日常の困りごとに対する支援などを、２４時間対応で行っているものです。\nその下、(6)、精神障害者地域生活サポート２４事業は、対象者を精神障害者とし、同じような支援をしているところでございます。\n続きまして、４５ページ、(7)、精神障害者交流スペース「憩いの場」でございますが、こちらは、精神障害者が交流できる場を設けまして、当事者やボランティアが集まり、食事会や創作活動などのグループ活動を行っております。\nその下、(8)、発達障害・思春期サポート事業になります。こちらは、思春期を迎えた児童と、その親の抱える悩みや課題に対する相談を支援することで、親のかかわり方を見直すきっかけや子どもたち自身の自己認知を高め、自立支援のきっかけとして行っているものです。平成２６年４月から、発達障害者支援施設ぷらーすに移設しましたことにより、思春期から成人期への切れ目のない支援ができるよう体制を整えているところでございます。\n４６ページをご覧ください。５、公共料金などの軽減。こちらは公共料金などのさまざまな各種軽減事業につきましては、記載のとおりとなっております。\n４８ページをご覧ください。【８】、その他の事業になりますが、最初に１、啓発事業といたしまして、１２月の障害者週間に記念のつどいを実施するほか、今年も障害者まつりとレクリエーション大会、を合同開催いたします。また、障害者作品展も引き続き実施する予定でございます。\nまた、今年度より新たに(5)、障害者の芸術活動支援事業といたしまして、アール・ブリュット展を開催するとともに、区内施設へのアート・ディレクターの派遣も行っております。\n４９ページにまいりまして、新たな事業といたしまして、(6)、障害者理解のための映画祭や、あるいは、(7)、障害者雇用・合理的配慮に関する講演会などを、企業を対象として行う予定になっております。\n２、障害者団体ですが、品川区は、障害を持つ方が組織する団体と連携を図りながら施策を進めております。各団体はこの表に記載のとおりでございます。\n最後になりますが、３、各種事業といたしまして、障害者表彰をはじめ被爆者見舞金、区長同意による精神障害者の医療保護入院を実施しています。\n５０ページから５１ページには、それぞれの事業における所得制限一覧表を、また５２ページ以降は、障害者の施設を載せさせていただいております。"},{"i":47,"speaker":"伊東生活福祉課長","text":"それでは、私のほうから、生活福祉課の事務事業についてご説明させていただきます。恐れ入ります、品川区福祉部事務事業概要、公的扶助編の１ページをご覧ください。\nまずはじめに、組織および職員数でございます。生活福祉課は、福祉部の一員であるとともに、品川区福祉事務所の構成員ともなっております。七つの係で構成されております。\n次の２ページになります。生活福祉課事務分掌でございます。生活福祉課は、品川区組織規則に定めております法外援護を中心とした事業、生活困窮者自立支援事業、そして、福祉事務所庶務規定に定めます生活保護法を中心とした事務事業を取り扱っているところでございます。\n福祉事務所庶務規定のほうでございますけれども、保護事務係につきましては、保護費の支払い、医療券、介護券の作成ならびに各種統計などを取り扱っているところでございます。相談係は、生活保護に関する相談、中国残留邦人等の円滑な帰国の促進及び永住帰国した中国残留邦人及び特定配偶者の自立の支援に関する法律に基づく支援事業を行っております。\n保護第一係から保護第五係につきましては、各地域センターの所管ごと、生活保護法に基づきます個別の支援事務を行っているところでございます。\n次の３ページにお進みください。生活保護法は、憲法第２５条に定める生存権の保障を具体化するもので、生活保護法の第１条から第４条までに基本原理が書かれてございます。\n(1)、基本原理といたしましては、第１条に国家責任による最低生活保障の原理、第２条に生活困難になった原因は問わないという保護請求権無差別平等の原理、第３条に健康で文化的な最低生活保障の原理、第４条に保護の補足性の原理と言いまして、保護を受けるためには、自分の能力、活用できるあらゆる資産を活用していただくことが定められているものでございます。\n(2)、保護の種類といたしましては、1)、生活扶助から8)、葬祭扶助までの８種類でございます。\n次の４ページにお進みください。(3)、保護の決定方法につきましては、右上に図を示しておりますけれども、厚生労働大臣が定める保護基準に基づき、最低生活費を計上した上で世帯全員の収入と対比し、不足分を保護費として支給させていただくものでございます。\n(4)、保護基準につきましては、例年基準改定が行われておりまして、４月１日現在の基準を記載してございます。生活保護基準改定の推移はこの表のとおりでございますが、一昨年８月の第６９次より、３カ年での改定で進められてきております。現在の第７１次の基準でございますけれども、標準世帯と申しまして、ご夫婦ならびに子どもの世帯につきましては、１５万１２０円となってございます。\n恐れ入ります、飛んで６ページにお進みください。(5)、保護の方法でございます。自宅で保護する居宅保護を原則にしておりまして、必要なときは、本人の希望によりまして、施設に入所して保護させていただくことになっております。\n(6)、品川区の現況でございますが、こちらにつきましては各年度の平均になっております。平成２６年度は４,７３４世帯、５,６２６人でございました。平成２５年度から比較いたしますと、世帯数で０.８％の増加となっているところでございます。\n2)、平成２５・２６年度の開始原因比でございます。平成２６年度の開始原因として多かったものは、預金の減少ということで２２.１％となっています。ほかに世帯主の傷病が２０.２％、定年・失業が１０％というふうに続いておりまして、最初の原因としては、このようにさまざまでございますけれども、結果的には経済的な要因がほとんどとなってございます。\n3)、生活保護を受給されている方の世帯構成ですけれども、高齢者世帯が最も多く５７％ほどになっているところです。\n次の７ページにお進みください。5)、医療扶助人員でございます。平成２６年度、生活保護受給者人数が５,６２６人のところ、医療を受けた方が４,７２４人、８４％でございます。入院されたことがある方が２４０人で、５.１％となっているところでございます。\n7)、介護扶助人員の実績でございまして、施設介護を受けていらっしゃる方が１４２人いらっしゃいます。\n次の８ページですけれども、8)、生活保護費の支出額でございます。平成２６年度の支出額は、平成２７年４月３０日現在でございますけれども、１１５億８,０２２万円余の保護費を支払ったところでございます。なお、平成２６年７月から就労自立給付金が創設されましたので、新たな項目となってございます。構成比は、医療扶助が最も多く、４３.６６％でありまして、生活扶助、住宅扶助、医療扶助の三つの扶助費で全体の９６.５％を占めております。\n(7)、法外援護につきましては、1)、学童生徒に対する夏季健全育成費から、次のページになりますけれども、一番下7)、小中一貫校標準服購入費支給まで７項目ございます。それぞれの実績は、各表のとおりでございます。\n次の１０ページですけれども、中国残留邦人等支援事業でございます。この事業は平成２０年４月から開始したもので、中国等からの帰国者に対する支援を行うものでございます。対象者は平成２６年度末現在で２８世帯、４４名で、支援内容は、生活費や住宅費などの不足分を生活保護に準じた形で支援するものでございます。\n１１ページにお進みください。４、低所得者の福祉ということで、(1)、高額療養費等支払費用の貸付けでございます。多額の医療費が必要で、その支払いが困難な人に対して資金を貸し付け、その療養を確保することを目的としているものでございます。貸付状況は下の表にあるとおりでございます。\n１２ページでございます。この４月からの新規事業であります。(2)、生活困窮者自立支援事業、生活困窮者自立支援法に基づく事業でありまして、生活困窮者への支援強化、困窮状態からの早期自立を図ることを目指しまして、暮らし・しごと応援センターを開設しました。相談や包括的な支援を実施しているところでございます。資料には記載しておりませんが、４月末時点で９６名の来所があり、相談を受けたところでございます。\n事業内容の２番目にあります住居確保給付金につきましては、平成２１年１０月から住宅手当緊急特別措置事業として実施しておりましたけれども、新法の適用となりまして、住宅支援給付から名称が変わって実施するものでございます。こちらの事業は、６５歳未満、離職２年以内の者であって、就労能力、意欲もあり、かつ住居の喪失、または喪失のおそれがある方を対象に、安心して就労活動ができるよう家賃に充てるための費用を支給するものでございます。平成２６年度の実績は、表にございますとおり３５人に支援したものでございます。\n以下、就労意欲喚起や就労前準備の支援を行う就労準備支援事業、子どものいる家庭へのカウンセリングや訪問支援を行う学習支援事業、家計の収支状況を分析し、アドバイスや金銭管理を行う家計相談支援事業、これらを活用しまして、安定した生活が継続できるよう支援していくものでございます。\n１３ページにいきます。５、行旅病人および行旅死亡人の取扱いでございます。行旅病人および行旅死亡人の取扱法に基づきまして、区内で発生した行旅病人の医療および救護ならびに死亡人の葬祭を行うもので、平成２６年度につきましては、死亡人として９件を取り扱った次第でございます。"},{"i":48,"speaker":"沢田委員長","text":"説明が終わりました。\nこれより、ただいまの説明に対する質疑に入りますが、先ほども申し上げたように、具体的な質疑は、今後、取り上げていく個々の案件の中で活発に行いたいと思いますので、その点を踏まえて、特にご確認したいことがございましたら、ご発言願います。"},{"i":49,"speaker":"のだて委員","text":"今、生活保護の話があったのですけれども、品川区が、昨年度１５.６‰で、東京都が２２.１‰、全国でも１７.１‰ということで、なぜ低くなっているのかということ。もしかしたら多くの方が知らないのではないかということがありますので、この見解をお聞きしたい。\nそれから、生活保護が、今年度から生活扶助費も下げて、冬季の加算も下げられるということで、この影響を受ける人数と、変わることによって、これからどうなっていくのかということをお聞きしたいと思います。"},{"i":50,"speaker":"伊東生活福祉課長","text":"保護率に関しましては、品川区の場合、一時的には上ったことがあったのですけれども、ここ数年は、微増の傾向になってございます。ほんの少しの増加という形で推移しております。\nご質問のあったところですけれども、生活保護の相談があった場合は、こちらのほうとしては、相談者の実情をよく聞いたうえで、該当すれば、当然生活保護でございますし、そうでなければ、今で言う生活困窮者自立支援法のほうでの支援を視野に入れつつ、対応しておるところでございます。\nそれからもう１点、住宅扶助のところでございますけれども、基準改定のほうは、区分が変わったということで、今まで、単身が５万３,７００円、２人から６人が６万９,８００円、７人以上が８万３,８００円だったのですが、７月以降、単身は５万３,７００円、２人世帯が６万４,０００円、３人から５人が６万９,８００円、６人が７万５,０００円、７人以上が８万３,８００円というように変更されるところでございます。\n影響ですけれども、金額的に考えますと、２人世帯のところに影響があるかと思うのですが、正確な数字はないのですけれども、２月１日の時点で、２人で生活されて、なおかつ６万９,８００円の住宅扶助を支給されている方を抽出してみたのですが、そのときに１７１世帯あったというところで、その方々は、少なからず影響があるのかと思っております。ただ、それぞれ世帯の状況に応じて経過措置もございますので、その辺で対応していくというようなことでございます。細かなところは、今、調査中ということでございます。\nもう１点、冬季加算の話でございますけれども、こちらにつきましても、国のほうからの基準ということで、単身で３,０８０円だったところが２,５８０円、これは１１月からの適用となっております。２人、３人、４人ということで、それぞれ金額が示されておりますけれども、説明は省略しますけれども、金額ベースでは若干下がっているというようなことでございます。これにつきましては、国のほうで、各地域の実情、それぞれの一般世帯との比較をしまして、そういう動向を確認したうえで、こういう金額が妥当ということで示されたものでありますので、我々としては、この基準に基づきまして実行していくというところでございます。"},{"i":51,"speaker":"のだて委員","text":"生活保護のところでは、国会の厚生委員会でも、付帯決議で周知をするようにということになっておりますので、ぜひ、広く周知をしていただきたいと思います。\nそれから、紙おむつの現金が新設されましたので、この周知をどういうふうにやっていくのかということと、緊急通報システムは命に係わることですので、安くなったので、この周知についてもどう考えているかということ。\nそれから、先日、東京では震度４の地震がありました。そこで、障害者が、エレベーターが停止して帰宅できないということがありまして、福祉避難所の体制等、そういったときの受け入れの要望がありまして、今、どういうふうに考えていらっしゃるかをお聞きしたいと思います。"},{"i":52,"speaker":"永尾高齢者福祉課長","text":"紙おむつの現金支給の周知でございますけれども、実際、４月から始めまして、従来使っている方については、当然、社会福祉法人のほうでやっております。在宅介護支援センターのほうでご相談あった方については、ケアマネージャーが個別で紹介をしているという状況になっております。"},{"i":53,"speaker":"大串福祉計画課長","text":"緊急通報システムの周知でございますが、こちらについても、ホームページ等々を活用して周知を行っておりまして、今現在、４月、５月の実績、やはり昨年に比べるとかなり増えてきているといったところでございます。"},{"i":54,"speaker":"中山障害者福祉課長","text":"まず、障害者の緊急通報の周知になりますが、計画相談の中で、ご相談に応じてそういったものの活用を勧めているところでございます。\nまた、先だっての地震でエレベーターがとまってしまったということですが、福祉避難所の開設というのは、もう少し大きな被害があったときに順次開設していくものになると思います。先だっての地震は、一時的にエレベーターの停止はございましたが、区内に大きな被害があったものではございませんでした。なかなかに難しいところではあるかとは思うのですが、日中であれば、エレベーターに乗れないときに、どこかの、例えば区のいろいろな施設でも結構ですし、あるいは、喫茶店に避難するということもございますし、福祉避難所ですとか、あるいは、二次避難所とか、そういったことは、もう少し大きな地震があったときの対応ということで、あのくらいの地震の被害であれば、そういったものの活用は今のところ考えていないところでございます。"},{"i":55,"speaker":"のだて委員","text":"今回、一人の障害者の方が家に帰れなくて、野宿になるのではないかみたいな事態にもなりましたが、一応、知り合いの方のうちに上げてもらって何とかなったということだったのですけれども、これからこういったこともあると思いますので、ぜひこれも考えていただきたいと思います。"},{"i":56,"speaker":"石田（秀）委員","text":"１点だけすみません、最初の福祉部長の説明のところで、国も２０２５年を見据えて、地域包括ケアという話があって、区もそれを見据えてやっていくという話だったのですけれども、これは、ソフト、もちろんハードがあって、ハード整備は、計画をしても、やはりあと１０年かかっていくのだろうというのは、それはそれでいいのですけれども、ソフトの部分で考え方をまとめていくのは、もっと早くそれをやっていって、それに向かってハードも整備していくというつもりで、私はいるのです。\nそこら辺の考え方は、ソフトについては今年決めるという話ではないわけですが、だけれどもやはり、この三、四年以内にはその部分はやっていくべきだろうと思っているのですけれども、感覚的なものは、それでいいのかどうかということだけ聞きたいと思います。"},{"i":57,"speaker":"榎本（圭）福祉部長","text":"今、委員からご質問がありましたけれども、やはり地域包括ケアというのは、あらゆる高齢者に関する環境を整えていくという形になっております。住まい、介護、医療、それから生活支援等、さまざまな分野がかかわっておりますので、区としましても、できるものからどんどん実現をしていかないといけないかなと思っております。ただし、全体像を見据えたうえで、どこから順番にやっていくかという形になりますので、特に今、医療と介護の部分に焦点が当たっていますけれども、それも含めながら進めていきたいと思っております。\n第六期事業計画の重点事業にも挙がっていますけれども、実際上、２０２５年は第九期になるのですけれども、なるべく早くそういうものに向けて形をつくっていきたいと考えております。"},{"i":58,"speaker":"鈴木（ひ）副委員長","text":"総合事業の中身については、次回、報告ということですので、そのときにいろいろとお聞きしたいと思いますけれども、今まで高齢者福祉課でされていたものが、今回、高齢者地域支援課になったわけですけれども、総合事業というのは、ホームヘルプとデイサービスだけだと思うのですけれども、それ以外の要支援の方の部分は介護保険に残りながら、その総合事業だけが地域支援課のほうに移したという、その考え方をひとつお聞かせいただきたいと思います。\nそれから、生活保護の問題なのですけれども、職員の態勢が、保護第１係から第５係までを合計すると４７人になると思うのですけれども、この保護世帯数が４,７３４世帯となると、平均でも１００世帯を持つことになるのではないかと思うのです。ここのところは、かなり負担が大きいのではないかという思いがしています。\n８０人以下にすべきだという、そういうことが国のほうからも示されていると思うのですが、この態勢に対しては、もっと増やして充実をさせることが必要なのではないかと思うのですが、その考え方についてひとつお聞かせいただきたいと思います。\nそれから、先ほども、保護率が１５.６‰で、東京都が２２.１‰、全国が１７.１‰ということで、かなり全国よりも、東京都よりも低いという状況になっているのですけれども、なぜ品川区がこれだけ低いという状況になっているのか、区としての捉え方がありましたら、お聞かせいただきたいと思います。"},{"i":59,"speaker":"松山高齢者地域支援課長","text":"まず、総合事業の要支援者の考え方でございますけれども、これまで、旧いきがい課で実施おりました一般介護予防事業も含めまして、今後、多様な介護予防事業を行っていくうえで整理するという観点もございますので、要支援者については、高齢者地域支援課で行ってまいります。"},{"i":60,"speaker":"伊東生活福祉課長","text":"ご質問の職員態勢の部分でございますけれども、確かに、職員数としては、こちらに示してある数字でございますが、そのほかに高齢者世帯自立支援員という、非常勤ですけれども、各１から５係のほうに配置しておりまして、そちらは主に高齢世帯で比較的安定している方を見ていただく形で対応しております。\nそのほかに、さまざまな非常勤、社会生活自立支援員ですとか、資産扶養等専門調査員ですとか、そういう方々も非常勤として雇ってございまして、なるべくケースワーカーの負担を分散させられるような形での体制をとってございますので、そういう形でやっていきたいと思っております。\nそれからもう１点、保護率の関係ですけれども、保護率としては、１５.６‰とういうことで、人口の関係で０.１ポイント下がってはございますけれども、上のほうの保護人員で見ますと、若干増加傾向にあるということは、先ほど、お話ししたとおりでございます。\n全国平均、東京都平均より低いというところは、都内の場合、結構大都市に生活保護受給者が多いと言われておりますけれども、東京都内でも、３０‰、４０‰の率の区もございます。品川区は地域特性といいますか、詳しくはあれですけれども、幸いにしてこの数字でございます。どうしても山谷地区とかは、過去のことからもどうしても多い、また、大阪とか、一部の地区が多いとか、横浜の一部の地区が多いとか、そういう現象はございますけれども、品川区の場合は、そういうところは入っていないということで、２３区で考えますと、平均より少し下のところでございます。"},{"i":61,"speaker":"鈴木（ひ）副委員長","text":"ケースワーカーの方は、実際問題、ほんとうに負担が重いということがあると思うのです。多い方は、一人で１００名を超えている方もいらっしゃるとお聞きしています。さまざまいろいろな課題を抱えた方を見ていただくということになりますので、ぜひそこの体制については、今後も充実していく方向でお願いしたいと思います。\nそれから、総合事業のほうは、要支援の方も全てこの地域支援課で行うということに、大きく変わったということで、ご説明を受けました。ここから要介護のほうに移っていく方が多いと思いますので、そこら辺の連携はよろしくお願いしたいと思います。"},{"i":62,"speaker":"沢田委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":63,"speaker":"沢田委員長","text":"ほかになければ、福祉部の事務事業概要につきましては、以上で終了いたします。\n続きまして、健康推進部および品川区保健所の事務事業概要について、一括してご説明願います。"},{"i":64,"speaker":"矢野健康推進部長・品川保健所長兼務","text":"それでは、私から、健康推進部の事務事業概要の全体的な部分について、ご説明させていただきます。お手元の冊子の中で、健康推進部事務事業概要（保健衛生編）の３ページをご覧ください、組織図がございます。\n健康推進部は、健康課と国保医療年金課および品川区保健所で構成されております。健康課は、部の庶務担当課でありますと同時に、保健衛生、健康づくり、地域医療連携など、国保医療年金課では、国民健康保険、国民年金、後期高齢者医療などを担っております。\n品川区保健所のほうは、地域住民の健康を支える公衆衛生の第一線機関として、地域保健法に基づき設置されておりまして、法令の定めにより保健所長が保健衛生に関する許認可等の独自の権限を持っている組織でございます。品川区といたしましては、区政全般の一貫性を確保するという趣旨から、品川区の組織条例の中で、健康推進部の事務分掌の中に保健所に関すること、という規定を入れることで、保健所に対する一定の調整権限を健康推進部に持たせるという形をとっております。\n品川区の組織体制、事務分掌等につきましては、品川区保健所庶務規定において定めております。\nこの組織図の中で、生活衛生課と保健予防課は本庁にございまして、区内全域を対象としております。生活衛生課は保健所の庶務担当課でありますと同時に、食品衛生や環境衛生などを、保健予防課は感染症対策や予防接種および精神・難病事業などの取りまとめを担当しております。\n品川、大井、荏原の三つの保健センターは、それぞれの管轄地域において母子保健や地域の健康づくり、精神保健相談など、あるいは難病患者の支援事業など、直接の事業を担当しております。\n全体として、健康推進部は、生れる前、つまり妊娠中から高齢者までの区民の皆様の健康をさまざまな面から守り、支援していくための事業を実施しております。\n今回、健康に関する課が一つにまとめられたことで、よりきめ細やかに事業に取り組んでまいりたいと思います。\n以上、健康推進部の組織と概略について、ご説明させていただきました。\nそれぞれの課の事務事業の内容につきましては、各課長からご説明させていただきます。説明には、この保健衛生編と社会保健編を使用いたしますので、よろしくお願い申し上げます。"},{"i":65,"speaker":"川島健康課長","text":"私からは、健康課所管の事務事業概要について、ご説明させていただきます。それでは、事務事業概要の保健衛生編を覧ください。冒頭、早速１ページの目次の一番上に誤字がございます。「健康福祉事業部」と書いてございますが、「健康推進部」に訂正をさせていただきます、申しわけございません。\nそれでは、健康推進部の保健衛生に関連する所管につきましては、健康課のほかに保健所の生活衛生課、保健予防課、保健センターがあるため、説明の際にページが飛ぶことがございますが、あらかじめご了承ください。\n３ページをごらんください。保健衛生、健康づくり、国民健康保険などを所管する部署としまして、今年度、健康推進部が新設されました。健康課と、国保医療年金課が配置されております。また、品川区保健所の中に２課、３保健センターが配置されており、健康課は健康推進部長と私を含めて、４月１日現在で２２名で組織されております。庶務係、健康づくり係、保健衛生係、公害補償係の四つの係でございます。\n続いて５ページをご覧ください。５ページには、健康推進部の健康課と保健所各課の事務分掌を記載してございます。\n９ページにお進みください。１、保健衛生の現状として、施策の考え方を示しております。生活習慣病の予防を中心として、区民の健康づくりにつながる環境をつくっていくということで、1)、区民の健康づくりの支援、2)、疾病対策の充実、3)、地域の医療体制の充実、これら三つの柱を基本に仕事に取り組んでおります。\n１４ページにお進みください。ここの表の中には、保健衛生関係予算を記載してございます。平成２７年度、保健衛生関係予算は３７億６２万４,０００円で、内訳はこの表のとおりです。\nここからまた、ページが少し飛びます。４８ページをご覧ください。９、休日診療・小児（平日・土曜日）夜間診療です。現在、内科小児科の休日診療は、品川、荏原両医師会診療所で９時から２２時まで、大井地区は９時から１７時まで輪番制で実施しております。歯科、柔道整復施術も、輪番制で同じく９時から１７時まで、調剤薬局は９時から２２時まで、品川、荏原両薬剤師会で実施しているところです。\nまた、昭和大学病院の協力で、平日夜間および第２、第４土曜日夜間に小児応急診療を行っております。残りの第１、第３、第５土曜日の夜間は、品川区医師会で内科小児科の診療、品川薬剤師会の調剤を実施しているところです。その実績を、５１ページまで記載しております。\n続いて５２ページをご覧ください。１０、かかりつけ医・歯科医・薬局制度促進です。それぞれ医師会、歯科医師会、薬剤師会に委託して実施しております。\n次の５３ページをご覧ください。１１、生活習慣病予防の記載がございます。こちらの表１１－１にありますとおり、品川区における死亡原因の第１位は、全国同様、悪性新生物、つまりがんとなっております。こうしたがんをはじめとする生活習慣病予防対策の一環として、５４ページから記載のあります健康診査等を実施し、疾病の早期発見、早期治療の促進に努めております。こちらにあります1)、品川区健康診査ですが、健康課で実施している健康診査は、４０歳以上の区民で、生活保護受給等の無保険者が対象となっております。\n５５ページ、2)、肝炎ウイルス検診は、これまでに一度も肝炎ウイルス検診を受けたことがない区民の方が対象です。\nその下、3)、３５歳からの健康診査は、３５歳以上、３９歳以下の区民の方が対象です。\n５６ページにお進みください。4)、女性の健康診査は、１６歳以上、３４歳以下の女性の区民が対象です。\n５７ページからは、(2)、各種がん検診について記載しております。1)、胃がん検診はバリウムによる検診で、平成２４年度からは、５８ページの2)、胃がんリスク検診を実施しております。５９ページの3)、子宮（頸部・体部）がん検診、それから６０ページの4)、乳がん検診、６１ページの5)、肺がん検診、６３ページの6)、大腸がん検診、それからその下の7)、前立腺がん検診、それから６４ページの8)、喉頭がん検診と、７種類のがん検診を実施しております。\n平成２６年度のがん検診の受診傾向といたしましては、胃がんリスク検診と肺がん検診、大腸がん検診の実績が伸びております。\n次は、６５ページにお進みください。成人歯科健康診査です。４０歳から７０歳までの５歳刻みの区民の方を対象に検診を実施するもので、今年度からは、希望者に簡易な歯のクリーニングを実施します。\n平成２４年度から、６６ページ中ごろに記載のあります障害者歯科健診を開始しております。\n６８ページにお進みください。１２、健康づくりの記載です。平成２６年度に、向こう１０年間の区民の健康づくり計画として策定しました、しながわ健康プラン２１に基づきまして、６９ページからの(2)、健康づくり推進委員事業、(3)、健康センター事業、それから飛びまして、７２ページからの(4)、健康づくり支援事業、７４ページにあります(5)、健康塾、(6)、ふれあい健康塾、７５ページの(7)、しながわ出会いの湯事業などを実施しているところです。\n続いて、７７ページにお進みください。１３、母子保健にまいります。(1)、不妊治療医療費助成ですが、件数、助成額は、表１３－１のとおり、年々交付件数が伸びております。\n(2)、妊産婦の保健ということで、2)、妊婦健康診査、それから、次のページの3)、妊婦・産婦歯科健康診査を実施しております。\nまた、ページが飛びますが、８５ページにお進みください。中ほどの4)、６カ月・９カ月児健康診査は、医療機関に委託しております。\n８９ページにお飛びください。３歳児の11)、むし歯予防フッ素塗布事業。それから、９０ページからの２）母子関係医療費助成を行っております。\nここでまたページが飛びますが、１２３ページをお開きください。１７、公害補償です。公害健康被害の補償等に関する法律に基づく公害認定につきましては、昭和６３年度以降、新規の認定は行われていません。１２４ページにありますように、品川区の認定患者数は７２９名です。医療費等の補償給付は、１２５ページ中段にありますが、平成２６年度、５億６,０２１万６４４円でした。\n１２５ページ、被認定者のための保健福祉事業を実施してございます。\nまた、１２６ページの公害健康被害予防事業としまして、１２７ページの公害健康相談、ぜん息健康教室、水泳教室等の事業を実施しております。\n１２８ページにお進みください。１８、大気汚染に係る健康障害者に対する医療費助成の申請受付です。こちらは東京都の事業ですが、区で申請の受付、審査、医療券の交付などの事務を行っております。品川区の認定患者数は２,８８２名です。\n最後に１２９ページ、１９、石綿による健康被害の救済給付受付です。アスベストによる健康被害の救済給付のための申請受付事務のみを区で行っているものです。"},{"i":66,"speaker":"高森国保医療年金課長","text":"私からは、別冊になりますが、健康推進部事務事業概要（社会保険編）に基づきまして、国保医療年金課の事務事業概要についてご説明をさせていただきます。\n１ページおめくりください。国保医療年金課では、国民健康保険事業、国民年金事業、後期高齢者医療制度の三つの業務を所管してございます。また、会計では、一般会計と国民健康保険事業特別会計、後期高齢者医療特別会計を担ってございます。\nもう１枚おめくりください、１ページでございます。事務分掌でございます。国保医療年金課では、保険事業係以下９係制をしいてございまして、職員数は９０名でございます。また、７４歳までが国民健康保険に加入いただきまして、７５歳になりますと、後期高齢者医療保険制度へと移行となります。\nそれでは、３ページ目をご覧ください。国民健康保険の事務事業概要でございます。昭和３４年国民健康保険法に基づきまして、全ての市町村および特別区は、国民健康保険事業を実施することが義務づけられまして、現在に至ってございます。国民皆保険の基盤となる制度として、ほかの被用者保険等の対象とならない自営業者の方や非正規雇用の方を中心とした保険制度でございます。\n４ページの加入状況でございますけれども、平成２６年度末、９万２,３９７人でございました。おおよそ、区民の４分の１程度が加入している状況でございます。また、外国人につきましても４,８３４人で、３カ月を超える在留資格の者が対象となってございます。\n次に、５ページへお進みください。３、保険給付でございます。被保険者がけがをしたり病気になった場合に、保険給付を行うことになってございます。内容につきましては、こちらに記載がございますが、1)、療養の給付、2)、療養費、少し飛びまして、大きなところでは、8)、高額療養費などがございます。\nまた、事前に申請いただきますと、入院された場合に、自己の保険の支払い額を自己負担限度額までする限度額適用認定書等の申請の受付けや交付も行ってございます。\n続きまして、１０ページをご覧ください。11)、その他の給付といたしまして、出産育児一時金４２万円、葬祭費７万円等の事業もやってございます。\n１１ページでございます。一番下でございますが、(7)、ジェネリック差額通知。医療費の抑制といたしまして、ジェネリックの差額通知によりまして、医薬品の差額が発生する方に通知を差し上げまして、ジェネリックの医薬品の利用拡大をＰＲしているところでございます。\n続きまして、１３ページをご覧ください。４、保険料でございます。国民健康保険料と後期高齢者支援金分の保険料、介護納付金分の保険料を合算いたしまして、納付をいただいているところでございます。算定につきましては、被保険者が均等に負担していただきます均等割額と、所得に応じて負担する所得割等で構成されているところでございます。\n国民健康保険料につきましては、６月から３月までの１０回払いということで、お支払いいただいくことなってございます。また、６５歳以上の年金受給者の方につきましては、年金からの特別徴収という形になってございます。\nそのほかにも減免、免除、軽減などの制度がございます。また、ご相談もなく保険料等をお支払いいただけない場合につきましては、必要に応じまして滞納処分等を行っているところでございます。保険料の収入状況でございますが、１４ページの表に記載してあるとおりでございます。\n次に、１５ページ、５、国民健康保険運営協議会。国民健康保険事業の適正な運営を図るために、区長の諮問機関といたしまして、国民健康保険運営協議会を設けまして、国民健康保険事業の運営に関する事業事項について審議をいただいているところでございます。\n次に、１８ページをご覧ください。７、人間ドッグ受診助成事業でございます。こちらの事業につきましては、平成２６年度からの新規事業でございまして、国保基本健診を受診せずに人間ドッグ等を受診した場合、被保険者の申請に基づきまして、費用の一部、８,０００円を限度に助成をしている制度でございます。保険料の未納がない方が対象となってございます。\n次に、１９ページをご覧ください。先ほど申し上げました８、国保基本健診・国保保健指導でございます。４０歳から７４歳までの被保険者を対象に、メタボリックシンドロームに着目した基本健診を実施しておりますが、２０ページの下の段のところに実績が載ってございます。平成２６年度の４０歳以上の対象者は６万４,７８７名、受診者につきましては２万３,８２３名でございます。\n次に、もう１ページおめくりいただきまして、２１ページをご覧ください。基本健診の結果、メタボリックシンドローム等の該当者、または予備軍などと判定された方に対しまして、保健師や管理栄養士によりまして、保健指導を実施いたします。また、生活習慣病の予防や生活習慣改善に向けた支援等を行っております。表の一番下ですが、平成２６年度の対象者は１,８９３名、保健指導の利用者は３６９名という形でございました。\n次に、２２ページでございます。９、広報活動でございます。事業の制度や理解を求めるために、「こんにちは国保です」、「わかりやすいこくほ」などを発行するとともに、広報誌「しながわ」等を通じまして広報活動に努めております。\n続きまして、もう１枚おめくりいただきまして、２４ページでございます。国民年金事業でございます。平成２１年に社会保険庁が解体されまして、日本年金機構が発足しております。国民年金事業のうち、財政や管理運営については国が担いまして、業務運営については、国から権限を委託されました日本年金機構、出先機関である年金事務所が行うようになりました。区では、年金事務のうちの一部、１号被保険者の加入や受給申請、諸届等の受付等、また、保険料の減免や学生納付の特例申請など、一部の窓口業務につきまして、法定受託事務として行っているものでございます。\n少し飛んで、２９ページをお願いいたします。２、資格、取り扱い被保険者につきましては、２０歳以上６０歳未満の自営者の方や、その家族や学生、無職の方が対象となってございます。受付件数につきましては、表のとおりでございます。\n次に、３１ページをご覧ください。３、保険料でございます。徴収につきましては、日本年金機構が行っておりまして、保険料につきましては、平成２７年度、定額保険料が月額１万５,５９０円、付加保険料が４００円となってございます。\n次に、３２ページでございます。さまざまな免除や納付の特例、納付猶予がございます。\n１ページおめくりいただきまして、３４ページをお願いいたします。４、給付でございます。年金の種類によりまして、受給要件、受給期間等がそれぞれ異なってございます。\n３６ページにお進みください。こちらのほうは支給金額を記載してございます。先ほど来、申し上げておりますように、年金の種類によりまして異なってけれども、一番上の老齢基礎年金につきましては、平成２７年度支給額、満額で７８万１００円という形になってございます。\n次に、少々飛んでいただきまして、４３ページでございます。後期高齢者医療制度でございます。こちらは、平成２０年４月に創設された制度でございまして、運営主体につきましては、東京都後期高齢者医療広域連合が担ってございます。広域連合と区が協力して適切な役割を分担を図りながら、安定した制度として運営をしているところでございます。こちらの被保険者は、７５歳以上の方、または６５歳以上の方で一定の障害のあると、広域連合が認定した方が対象となってございます。\n４４ページでございます。３、医療費の給付でございますけれども、こちらは、後で見ていただけるとおわかりになりますが、国民健康保険と同様でございます。\n１枚おめくりいただきまして、４６ページをご覧ください。被保険者が医療保険の窓口で診療を受けた際にお支払いいただく一部負担金につきましては、１割負担を基準としてございます。また、現役なみ所得者につきましては、３割負担をお願いしているところでございます。\n１ページおめくりいただきまして、４７ページをご覧ください。４、保険料でございます。医療費全体から公費負担分が５割、現役世代からの支援金４割を除く１割分につきまして、加入者の保険料で賄っている仕組みでございます。保険料の算定につきましては、均等にお支払いいただく均等割額と、所得に応じていただく所得割額の合計額という形になってございます。\nまた、(4)、保険料の軽減措置、(5)、保険料の減免等でございますが、国民健康保険と同様に、所得の低い方を対象にいたしまして、軽減措置が設けられているところでございます。\n最後に４９ページでございます。５、保健事業でございます。国民健康保険と同様に、後期高齢者の健康診査、また、人間ドッグの助成についても区として行っているところでございます。\n最後に５０ページでございますが、老人保健医療につきましては、制度が既に廃止となってございます。"},{"i":67,"speaker":"高山生活衛生課長","text":"それでは、私のほうからは、生活衛生課の事業につきましてご説明させていただきます。使います事務事業概要は、保健衛生編のほうにお戻りいただきまして、ご説明をさせていただきます。\nまずは、たびたびで恐縮ですが、３ページにお戻りください。こちらは健康推進部の組織図となっておりますが、健康推進部、健康課、国保医療年金課の下に、品川区保健所生活衛生課がございます。生活衛生課の中には、庶務係をはじめといたしまして、医薬環境衛生担当、食品衛生担当、検査担当の１係３担当、人数で申しますと３５名で構成されております。業務内容といたしましては、保健所全般に関わります庶務的な業務と、生活環境、食品、医薬、動物愛護などの衛生に係わる業務を担当しております。\nおめくりいただきまして、５ページをごらんください。事務分掌ございます。中ほどより下に品川区保健所、Ｉ、生活衛生課の記載がございますので、後ほど、ご確認願います。\n少し飛びまして、１６ページをご覧ください。２、衛生統計および調査とございます。こちらは、人口動態調査令等の国の法律に基づきまして、保健衛生行政の企画および実施の指針ならびに行政効果の判定などの資料を得るために衛生統計を実施するものでございます。こちらの内容につきましては、１６ページから始まりまして２１ページまで続いておりますので、後ほどご確認ください。\nお手数ですがおめくりいただきまして、２９ページをご覧ください。４、環境衛生とございます。こちらは、地域の環境衛生水準の確保と向上を図り、良好な生活環境を保持することを目的としております。環境衛生関係の施設につきましては、こちらの表４－１にございますように、平成２６年度末で、理容所、美容所、クリーニング所等を合わせまして５,７７５カ所でございます。こちらの施設に関します監視指導、開設許可のほかに、おめくりいただきまして、３１ページの(2)、特定建築物の図面審査および検査指導にありますように、特定建築物といった施設の図面審査、検査指導なども行っているものでございます。\n同じページの(3)、生活環境に関する相談および検査指導の項目の中に、貯水槽、水道施設や住居環境等、生活環境全般に関する相談などへの対応につきましても記載がございますので、ご覧ください。\nおめくりいただきまして、３５ページをお開きください。５、医薬衛生とございます。(1)、医事衛生でございますが、こちらは、医療法その他の関係法令などに基づきまして、医療機関等の開設許可や監視指導などを行っているものでございます。\nおめくりいただきまして、３６ページでございます。中ほどより下に表５－６がございます。こちらは、医療相談コーナーの対応件数が載っているものでございます。こちらほうは、平成２１年度から、区民の方々からの医療に関する相談に対応する目的から設置しているものでございまして、患者と医療機関の良好な関係を構築するための支援としてさまざまな相談をお受けしているところでございます。\n同じ３６ページの下のほうに、(2)、薬事衛生とございます。こちらは、医薬品、医療機器等の品質、有効性および安全性の確保等に関する法律などの法令に基づきまして、薬局などの開設許可、また監視指導などを行っているものでございます。平成２６年度には、これまで親しまれてきた薬事法の名称が、改正によりまして、医薬品・医療機器等法へと変更されております。法令の名称が変わりましたが、引き続き監視、指導、そして情報提供などに努めているところでございます。\nおめくりいただきまして、３８ページには業態別の施設一覧が掲載してございます。\nお移りいただきまして、ページの右側、３９ページをご覧ください。６、食品衛生とございます。こちらは、飲食による危害の発生を防止して、健康の保護を図ることを目的としております。食品衛生法などの関係法令に基づきまして、飲食店などの許可、監視指導を中心に業務を行っているところでございます。食品衛生法や東京都の食品製造業等取締条例などに基づきます許可や届出を要する食品施設数は、平成２７年３月末現在、１万６,２３９施設となってございます。\n１枚おめくりいただきまして、４０ページをご覧ください。(8)、衛生教育とございます。こちらにつきましては、食品の安全を守るために、営業者の自主な管理体制の確立を目指すものでございまして、衛生講習会、その他実施しているところでございます。また、業態別の施設数の内訳につきましては、右側の４１ページから４３ページまで記載がございますので、ご確認ください。\n次に、４４ページをご覧ください。７、獣医衛生とございます。こちらは犬、猫に関する事業を行っておるものでございまして、まず犬につきましては、(1)、狂犬病の予防等、狂犬病予防法に基づきます畜犬の登録や狂犬病予防注射を実施しているところでございます。\nまた、(2)、飼い猫（飼い主のいない猫）の不妊・去勢手術費助成事業を行っているところでございます。直近３年間の実績につきましては、同じページの表７－２に記載がございますので、ご覧ください。\nまた、区民等への情報提供でありますとか、日常的な啓発などにつきましては、犬のしつけ方教室や猫の飼い方のセミナーなど、東京都獣医師会品川支部と協働しまして実施してきているところでございます。都会における犬、猫等のつき合いなどについてのご理解を深めていただきまして、近隣等とのトラブルを防いでいただくとともに、人と動物が共生できるまちづくりを目指しているところでございます。\n最後となります、４５ページをご覧ください。８、検査業務でございます。こちらにつきましては、品川第一地域センタービル内に検査室を設けておりまして、さまざまな検査を実施しているところでございます。地域の保健衛生、環境の向上を目的として、健康の維持増進、安全な食生活の確保、良好な生活事業の保持等、区民の健康を守る施策に対しまして、科学的な証拠を提供する役割を担っております。主にふん便の検査、そして安全な食生活のための食品微生物検査など、各種検査を幅広く実施しているところでございます。"},{"i":68,"speaker":"舟木保健予防課長","text":"続きまして、保健衛生編９２ページからの感染症予防、特殊疾病、精神保健福祉について、保健予防課から説明いたします。\n保健予防課は主に感染症、予防接種の事業を担当しております。特殊疾病、いわゆる難病と精神保健福祉につきましては、実際の区民対応は三つの保健センターで行っておりますが、取りまとめは保健予防課で行っておりますので、ここで一緒に説明させていただきます。\nまず、９２ページ、１４、感染症予防です。感染症対策は、患者発生時だけでなく、平常時からの発生動向調査、予防接種などの予防対策も重要です。\n右側の９３ページ、上段をご覧ください。エイズ予防対策につきましては、２０歳代、３０歳代の若い世代にＨＩＶ感染者が増加しており、普及啓発と、相談、検査体制の充実に努めているところです。\n９３ページ下段の表１４－１に実績を示しておりますが、エイズ・ＨＩＶ相談につきましては、５６５件、ＨＩＶ抗体検査は３０６件、ＨＩＶ抗体即日検査は８３件となっております。\n９４ページ、９５ページです。こちらは、新型インフルエンザ、エボラ出血熱、デング熱対策について書いてあります。西アフリカで流行が続いているエボラ出血熱に対する対策や、昨年夏、約７０年ぶりに国内感染患者の発生を認めたデング熱への対応について、今回、追加しております。\n９６ページから９７ページは、感染症の全数届出疾患の届出状況です。昨年度は、感染症法の改正により、二類全数届出疾患に１２番の中東呼吸器症候群と、１４番の鳥インフルエンザ（Ｈ７Ｎ９）、五類の全数届出疾患に７５の水痘（入院例に限る）が加わりました。\n次の９８ページですが、こちらは、定点届出疾患となっておりまして、区内のあらかじめ定められた医療機関より、毎週届け出のあるものとなります。平成２５年と比べますと、伝染性紅斑、ヘルパンギーナ、インフルエンザが増加し、感染性胃腸炎の減少が見られております。\n９９ページにお進みください、予防接種でございます。区では、法律で定められている定期接種のほか、独自施策として、任意予防接種への助成を行っております。表の下のほうにありますＨｉｂワクチン、子宮頸がん予防ワクチン、小児用肺炎球菌ワクチンの３ワクチンは平成２５年４月に、水痘と高齢者肺炎球菌は平成２６年１０月に、任意接種から定期接種へと変更となりました。\nまた、下から２番目の風しん緊急対策ですが、平成２４年から見られた首都圏を中心とした全国的な風しんの流行を受けまして、平成２５年３月から予防接種の全額助成を実施しております。\nまた、平成２６年度からは、区独自施策としてＢ型肝炎ワクチン接種費用の一部助成を実施しております。\n次に、１００ページをご覧ください。(2)、結核対策です。結核と診断され、届け出を受けた保健所が、必要に応じて就業制限、入院勧告、また接触者の検診を行うこととなっております。\n次の１０１ページから１０５ページにかけましては、平成２６年度の登録患者の状況、検診の状況等を示しております。品川区では、１０２ページの表１４－６にありますように、毎年８０名前後の結核患者が登録されております。\n次の１０３ページの表１４－７にもありますように、結核患者は高齢者だけでなく、若年層や３０歳代、４０歳代の働き盛りの年齢層にも発生しております。\n次に、１０６ページをご覧ください。１５、特殊疾病、いわゆる難病でございます。１０６ページから１０７ページにありますように、平成１４年以降、多くの疾患が助成対象に追加されております。難病の患者に対する医療等に関する法律が平成２７年１月から施行され、国の指定難病が５６疾病から１１０疾病に拡充されました。１０８ページから１１１ページの表に詳細を示しましたが、平成２６年度は３,０００名以上の申請を受け付けております。\n続きまして、１１２ページから１１４ページをご覧ください。区では、医療費の公費負担に加えまして、(2)、在宅難病患者訪問診療事業、(3)、在宅難病患者・家族療養支援事業、(4)、在宅難病患者等訪問介護・日常生活用具給付事業等を実施しているところです。\n次に、１１５ページをご覧ください。１６、精神保健福祉です。こころの健康づくり事業、精神障害者の社会復帰支援などの事業を行っているところです。また自殺対策につきましては、平成１９年度から、うつ・自殺予防対策を開始しております。\n下の表１６－１をご覧ください。こころの健康相談および訪問事業につきましては、複雑かつ困難な相談案件が増加しているのが特徴です。\n１１６ページの中段、表１６－２は相談の内訳を示しております。統合失調症だけでなく、認知症、アルコール・薬物依存症、うつ、神経症など多くの疾患が見られ、多様な対応が必要となっております。\nそのほか、１１７ページから１２１ページにありますように、精神科専門医による相談、社会参加促進事業、家族支援など、さまざまな事業を実施するともに、予防啓発に努めているところでございます。"},{"i":69,"speaker":"太田品川保健センター所長","text":"私からは、保健師、栄養士、歯科衛生士の各職種の業務について、また、健康づくり事業、母子保健事業の中で保健センターが担当している事業について、ご説明させていただきます。\n３ページにございますように、保健センターは、品川、大井、荏原の３カ所に分かれており、職員数は記載のとおりです。またそれぞれの事務分掌も、６から８ページにございます。また、その３センターの管轄地域と人口は１０ページにございます。\nでは、２２ページまでお進みください。３、保健衛生の相談・指導です。まず、(1)、保健師の活動です。保健師は、乳児から高齢者まで全ての年代を対象とて、こころと体の健康づくりや疾病予防、難病等の方の在宅療養支援、精神障害者生活支援、社会復帰支援などの業務に取り組んでおります。\n２３ページの表および２４ページのグラフが、平成２６年度の保健師の個別援助活動状況の実績をまとめたものですが、精神保健福祉分野と妊産婦、乳幼児といった母子保健分野の対応が中心となっております。\n続きまして２５ページ、(2)、栄養士の活動です。栄養士は、食生活、栄養の面から健康増進、疾病予防を目的とした相談、講演会を実施し、また、給食施設の指導、飲食店等の業者指導を実施しております。２５ページから２７ページにわたり、一般栄養指導、給食施設指導、業者指導の実績を掲載しております。\n続きまして２７ページ下段から２８ページの上段にかけてですが、(3)、歯科衛生士の活動でございます。歯科衛生士も、乳幼児から高齢者までを対象とした、また障害のある方を対象とした、歯と口の健康づくりを目的に健診、相談、健康学習などを実施しております。\nさらに２８ページの下段、(4)、実習生指導ですが、保健師等の保健医療職を目指す学生の実習指導も保健センターの活動として重要なものの一つとなっております。\n以上が、保健師、栄養士、歯科衛生士の活動状況です。\n次に、健康づくり事業の中で保健センターが担当しているものについて説明させていただきます。６８ページにお進みください。健康づくり事業については、１２、健康づくりとして掲載しております。\n６９ページ、(2)、健康づくり推進委員事業に関しては、保健センターは健康課と連携し、１３地区健康づくり推進委員会の地域における健康づくり活動を支援しております。\n続きまして、７２ページからの(4)、健康づくり支援事業の中の７３ページ、5)、健康大学しながわについてです。これは平成２１年度から３保健センターが担当で開始した事業で、この大学で学ばれた方が、地域で健康づくり活動に活躍していただくことを目的とし、公開講座、運動講座、コミュニケーション講座、健康探求講座の４種類の講座を半年かけて実施しております。卒業生は、地域健康づくりグループとして、地域での健康学習活動に取り組み、また、企画運営委員として健康大学しながわの企画運営にも携わっております。\n続きまして７６ページ、(8)、健康学習でございます。これには、今ご説明させていただきました健康大学しながわや、乳幼児の健診事業の際に行う集団指導等を含めた所内健康学習のほかに、保健センターが地域のグループ、団体などからの依頼に応じて実施する出張健康学習と、地域の自主グループ活動の育成支援を行う地域支援型の健康学習があります。\n以上が、保健センターが担っている健康づくり事業についてです。\n次に、母子保健事業の中で保健センターが担当しているものについて、説明させていただきます。母子保健事業につきましては、７７ページから１３、母子保健として記載しております。\nまず、７７ページ、(2)、妊産婦の保健ですが、この中では、1)、母子健康手帳の交付と、８０ページ、4)、妊婦への支援以降が保健センターで実施している事業です。4)、妊婦への支援では、若年、高齢、多胎、妊娠高血圧症候群、その他、心身に疾患、障害のある妊婦について、保健師が訪問、電話などにより相談支援を実施しております。\n5)、健やか親子学習でございますが、妊娠期から育児期までの保護者を対象とした教室、講演会などが列挙されています。単なる知識、情報の提供にとどまらず、親同士の交流、仲間づくり、グループワークなどの機会を設け、子育て支援、育児不安の軽減を図っております。\n８２ページ冒頭からの6)、食からの子育て支援です。妊娠期から育児期にかけて、食育をテーマに各種教室、相談を実施しております。\n続きまして、８３ページをお開きください。(3)、乳幼児の保健についてです。乳幼児の各種健診等の1)、すくすく赤ちゃん訪問事業・電話による育児相談ですが、これは以前から母子保健法に基づき実施していた新生児訪問事業に、児童福祉法に基づく事業である乳児家庭全戸訪問事業、こんにちは赤ちゃん事業を合わせたものとして、平成１９年度から実施している事業です。生後４カ月までの全ての乳児を対象として、育児支援、育児不安の解消、さらには虐待予防を目的として、保健センターだけではなく、児童センターおよび民生児童委員の方々の協力も得ながら、訪問により相談、助言を行っています。\n次に、８４ページ最下段以降、乳幼児の健康診査についてご説明申し上げます。区が提供する健診には、基本的には８４ページの3)、４カ月児健康診査、８５ページの4)、６カ月児・９カ月児健康診査、８６ページの6)、１歳６カ月児健康診査、８７ページの8)、３歳児健康診査がございます。これらのうち、４カ月児健診、１歳６カ月児健診および３歳児健診については保健センターで実施、いわゆる直営実施で、６カ月児・９カ月児健診は、都内契約医療機関に委託して実施しております。\n１歳６カ月児健診と３歳児健診は、母子保健法で区市町村に実施が義務づけられている健診で、小児科医による健診、歯科医による健診に加え、心理相談員、保健師、栄養士、歯科衛生士が相談、指導を行い、発育・発達の遅れや疾病の早期発見にとどまらない、子育て支援全体を視野に入れた健診を行っています。\n８８ページの10)、歯科衛生相談等から８９ページ13)、歯科衛生指導教育事業までは、母子保健分野の歯科保健事業が列挙されております。\nまた、一連の健診の結果、発育、発達、心理面で経過観察が必要とされた乳幼児については、８９ページ最下段にあります14)、乳幼児経過観察、15)、発達健康診査、16)、心理相談、経過観察の各事業でフォローアップしております。\n以上が、乳幼児およびその保護者を対象とした訪問事業、健診、相談事業の概要です。\n最後に、９０ページ、母子関係医療費助成についてです。区には中学３年生までを対象とした子どもすこやか医療費助成制度がありますが、母子保健分野では、ここに挙げましたような各種医療費助成制度があります。区あるいは東京都が実施主体で、保健センターが申請受付窓口になっております。\n以上、保健師、栄養士、歯科衛生士の業務および健康づくり事業、母子保健事業の中で保健センターが担当している事業について、その概略を説明いたしました。"},{"i":70,"speaker":"沢田委員長","text":"説明が終わりました。\n本件につきまして、ご質疑等ございましたら、ご発言願います。"},{"i":71,"speaker":"のだて委員","text":"国民健康保険ですけれども、今年、値上げがされると思うのですが、その通知がいつになるかということをお教えください。"},{"i":72,"speaker":"高森国保医療年金課長","text":"現在、出力されておりまして、点検中で、たしか６月１７日だったと思います。"},{"i":73,"speaker":"沢田委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":74,"speaker":"沢田委員長","text":"ほかになければ、事務事業概要につきましては、以上で終了いたします。\n────────────────────────────────────────────\n３ その他"},{"i":75,"speaker":"沢田委員長","text":"次に、予定表３のその他を議題に供します。\nその他で何かございますか。"},{"i":76,"speaker":"大串福祉計画課長","text":"平成２７年度の電力節減方針について、ご報告をしたいと思います。お手元の資料をご覧ください。\n品川区では、東日本大震災以降、電力受給の逼迫する夏季期間において、区として節減目標を定めまして、電力節減対応策に積極的に取り組んできております。\n本件は、本日、建設委員会においてご報告する予定となっておりますが、それぞれが所管する施設に係わることでもあるため、本委員会においても、同じ資料によりご説明をさせていただきます。\nまず１、４月以降の電力需給でございますが、当面、安定供給を確保できる見通しではありますが、火力発電所のトラブル、猛暑の影響等により電力の供給不足に陥るおそれが依然としてあるため、今年度も夏期（７月～９月）を中心に積極的に節電に取り組むことといたします。\n次に、２、節電目標は、昨年度と同様に平成２２年度比マイナス１５％といたします。ただし、利用者の健康保持など、業務や施設の特性等によりまして、マイナス１５％の達成が困難な場合は、別途目標を定めることといたします。\n次に、節電にあたり基本的な考え方は４点でございます。(1)から(4)でございます。\nまず、(1)、昼の時間帯を中心に、(2)、区民生活に大きな影響を及ぼす業務や施設においては必要最小限とし、(3)、区民向け貸し出し施設については、区民サービスの低下を極力招くことのないように節電に取り組んでまいります。また、(4)、イベント実施の際は、照明、空調の設定を控えるなど努めてまいります。\n次に、３、電力削減の基準でございますが、平成２２年度と比較した月間使用量といたします。\n最後に、４、区民、区内事業者への節電の呼びかけは、既に５月１日からサマールックキャンペーンを展開しており、ポスター、チラシ等を通じて引き続き節電の協力をお願いしているところでございます。\nまた、今年度も、猛暑への対応といたしまして、地域センターやシルバーセンター等区有施設の一部を活用できる避暑シェルターをご用意いたします。"},{"i":77,"speaker":"沢田委員長","text":"報告が終わりました。\nただいまご説明がありましたとおり、本件に関しましては、本日、建設委員会において、電力削減方針の概要説明が行われております。\nこの場で特に確認しておきたいことはございますか。"},{"i":78,"speaker":"いながわ委員","text":"厚生委員会所管の施設で避暑シェルターになるところは、あるのかどうなのか。たしか、避暑シェルターになると、たしか水分の補給もできるようになると思うのですが、その箇所数だけ教えてください。"},{"i":79,"speaker":"松山高齢者地域支援課長","text":"シルバーセンターが、その避暑シェルターとしての役目を果たしております。"},{"i":80,"speaker":"いながわ委員","text":"シルバーセンターは何カ所かあると思うのですけれども、違う所管の施設で、シェルターと書いた旗がその施設の中に入ってはためいていたのです。こういうものは外に出さないと意味がないと思いますが、そういうところにも十分配慮していただいて、外から見えると、ここはシェルターになっていると利用される方がいらっしゃると思いますので、ぜひ、そういうところも気をつけていただければと思います。"},{"i":81,"speaker":"沢田委員長","text":"ほかにございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":82,"speaker":"沢田委員長","text":"ないようですので、これで本件を終了いたします。\nほかにないようですので、私のほうから、２点のご案内を申し上げます。\nさきの本会議において、議長からもお話がありましたが、議会の活性化の観点から、委員会として、積極的に所管事務調査に取り組んでいく必要があると考えております。\nつきましては、年間を通して協議したい課題や調査事項等につきまして、委員の皆様からご発言をいただき、委員会日程等を考慮しながら、できる限り調査していきたいと考えております。参考までに、過去の調査項目については、お手元にお配りしております。それでは、所管事務調査について、ご意見等がございましたら、ご発言願います。"},{"i":83,"speaker":"石田（秀）委員","text":"私も、先ほど、質問させていただいたけれども、地域包括ケアは、ほんとうに今やっていくべきだろうと思っています。ただ、先ほど、福祉部長からも話があったように、これは範囲が非常に広いということもありますので、介護、医療、それから高齢者の健康長寿、体力づくり、健康づくりみたいなところから入っていくのがいいのかなと、私は思います。特に今、動き出しているところもあるのはそこら辺かと思うので、大原則は地域包括だけれども、今入れる医療、介護、健康づくり、こういうところから入りながら、１年間やっていけることはたくさんあると思うので、積極的に取り上げていただければと思います。"},{"i":84,"speaker":"沢田委員長","text":"ほかに何かございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":85,"speaker":"沢田委員長","text":"それでは、ただいまいただきましたご意見も含め、調査したいテーマがございましたら、６月１５日月曜日までに、文書にて事務局のほうに提出していただきたいと思います。\n日程的なこともございますので、提出されましたそれぞれのテーマにつきましては、資料等の準備などを含め、調査が可能か、正副委員長と理事者で協議させていただき、次回、６月２９日、もしくは３０日の委員会で調査項目について決定していきたいと思います。\nなお、所管事務調査のまとめにつきましては、正副委員長会において、議長より引き続き積極的に取り組んでいきたいとのお話がありましたので、あわせてご報告いたします。\n次に、行政視察についてですが、６月２９日もしくは３０日の委員会で、今年度の行政視察の調査事項、視察先について、委員の皆様からご意見を頂戴したいと思いますので、よろしくお願いいたします。\nまた、日程につきましても、例年１０月の最終週頃に行っておりますが、次回の委員会の中で、皆さんのご意見をいただきたいと思います。\n以上で、本日の予定は全て終了いたしました。\nこれをもちまして、厚生委員会を閉会いたします。\n○午後 ３時５０分閉会"}]});
